/* Logotipo DIPRA (provisto por Nicolás) — incrustado para que el artefacto
   funcione de forma autónoma, sin depender de un host externo. */
const DIPRA_LOGO = "data:image/png;base64,";

const FONT_LINK_ID = "dipra-fonts";
function useFonts() {
  useEffect(() => {
    if (document.getElementById(FONT_LINK_ID)) return;
    const link = document.createElement("link");
    link.id = FONT_LINK_ID;
    link.rel = "stylesheet";
    link.href =
      "https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=Inter:wght@400;500;600;700&family=IBM+Plex+Mono:wght@500;600&display=swap";
    document.head.appendChild(link);
  }, []);
}

/* This sandbox's Tailwind build only ships the pre-defined base utility
   classes — arbitrary-value classes like bg-[#1E8449] never get compiled
   and silently render as nothing. Every brand color and translucent overlay
   in this app is therefore defined here as real CSS and applied via plain
   class names (dp-*) instead of arbitrary Tailwind syntax. */
const STYLE_TAG_ID = "dipra-styles";
function useDipraStyles() {
  useEffect(() => {
    if (document.getElementById(STYLE_TAG_ID)) return;
    const style = document.createElement("style");
    style.id = STYLE_TAG_ID;
    style.textContent = `
      .dp-muted { color: #7A857F; }
      .dp-ink { color: #12161B; }
      .dp-body { color: #4A534F; }
      .dp-text-brand { color: #1E8449; }
      .dp-alert { color: #D14343; }
      .dp-text-amber { color: #C9871D; }
      .dp-text-nav { color: #B9CFC0; }
      .dp-text-faint { color: #9AA39C; }
      .dp-text-sidebar-muted { color: #8FAE9C; }
      .dp-text-tagline { color: #5B655F; }
      .dp-text-heading { color: #0E1210; }
      .dp-text-white-80 { color: rgba(255,255,255,0.8); }
      .dp-text-white-50 { color: rgba(255,255,255,0.5); }

      .dp-bg-brand { background-color: #1E8449; }
      .dp-bg-app { background-color: #F3F6F2; }
      .dp-bg-alert { background-color: #D14343; }
      .dp-bg-amber { background-color: #C9871D; }
      .dp-bg-ink { background-color: #12161B; }
      .dp-bg-heading-dark { background-color: #0E1210; }
      .dp-bg-faint { background-color: rgba(0,0,0,0.05); }
      .dp-bg-scrim { background-color: rgba(0,0,0,0.3); }
      .dp-bg-white-5 { background-color: rgba(255,255,255,0.05); }
      .dp-bg-white-10 { background-color: rgba(255,255,255,0.1); }

      .dp-border-brand { border-color: #1E8449; }
      .dp-border-alert { border-color: #D14343; }
      .dp-border-amber { border-color: #C9871D; }
      .dp-border-lime { border-color: #A8CC3C; }
      .dp-border-hairline { border-color: rgba(0,0,0,0.1); }
      .dp-border-faint { border-color: rgba(0,0,0,0.05); }
      .dp-border-white-10 { border-color: rgba(255,255,255,0.1); }

      .dp-divide-faint > * + * { border-color: rgba(0,0,0,0.05); }

      .dp-focus-brand:focus { border-color: #1E8449; }
      .dp-focus-ring-brand:focus { box-shadow: 0 0 0 3px rgba(30,132,73,0.15); }
      .dp-hover-brand-dark:hover { background-color: #14622F; }
      .dp-hover-alert:hover { color: #D14343; }
      .dp-hover-ink:hover { color: #12161B; }
      .dp-hover-brand-text:hover { color: #1E8449; }
      .dp-hover-border-brand:hover { border-color: #1E8449; }
      .dp-hover-bg-dark:hover { background-color: #181D1A; }
    `;
    document.head.appendChild(style);
  }, []);
}

