function tonoEscala(n) {
  if (n <= 3) return "dp-bg-alert";
  if (n <= 5) return "dp-bg-amber";
  return "dp-bg-brand";
}

// Para pilares donde un valor alto es negativo (ej. estrés), se invierte
// la escala antes de asignar el color: 10 se lee como "malo" (rojo).
function tonoEscalaPilar(valor, invertido) {
  const efectivo = invertido ? 11 - valor : valor;
  return tonoEscala(efectivo);
}

function EscalaUnoADiez({ value, onChange, readOnly, invertido }) {
  const v = Number(value);
  return (
    <div className="flex gap-1">
      {Array.from({ length: 10 }, (_, i) => i + 1).map((n) => (
        <button
          key={n} type="button" disabled={readOnly}
          onClick={() => onChange(String(n))}
          className={`w-6 h-6 rounded-md text-[10px] font-mono font-semibold flex items-center justify-center transition-colors ${
            value !== "" && n <= v ? `${tonoEscalaPilar(v, invertido)} text-white` : "dp-bg-faint dp-muted"
          } ${readOnly ? "" : "hover:opacity-80"}`}
        >
          {n}
        </button>
      ))}
    </div>
  );
}

