/* ---------------------------- Storage hook -------------------------- */

// Repara datos guardados con versiones anteriores del esquema — evita que la
// app se rompa cuando el navegador ya tenía clientes creados antes de agregar
// semanas múltiples, antecedentes, campos extra, etc.
function migrarCliente(c) {
  const cli = { ...c };
  if (!cli.plan) cli.plan = nuevaSemana ? { semanaActivaId: null, semanas: [] } : cli.plan;
  if (cli.plan && !cli.plan.semanas) {
    const s = nuevaSemana(1, cli.plan.semana || "", "");
    if (Array.isArray(cli.plan.dias)) s.dias = cli.plan.dias;
    cli.plan = { semanaActivaId: s.id, semanas: [s] };
  }
  if (cli.plan && (!cli.plan.semanas || cli.plan.semanas.length === 0)) {
    const s = nuevaSemana(1);
    cli.plan = { semanaActivaId: s.id, semanas: [s] };
  }
  if (cli.plan && !cli.plan.semanaActivaId) cli.plan.semanaActivaId = cli.plan.semanas[0].id;
  cli.plan.semanas.forEach((s, i) => { if (!s.numero) s.numero = i + 1; });

  if (!cli.fms) cli.fms = emptyFms();
  if (!cli.fms.seguimientoPropio) cli.fms.seguimientoPropio = {};
  if (!cli.sesiones) cli.sesiones = [];
  if (!cli.prHistorial) cli.prHistorial = [];
  if (!cli.antecedentes) cli.antecedentes = { morbidos: "", qx: "", partos: "", hormonal: "", cronicas: "", respiratorios: "", sistemicos: "", neurologicos: "", cardiacos: "", cancer: "", deporte: "", lesiones: "" };
  if (!cli.camposExtra) cli.camposExtra = [];
  if (!cli.movilidadEsferas) cli.movilidadEsferas = [];
  if (!cli.evaluacionesCustom) cli.evaluacionesCustom = [];
  if (!cli.composicionCorporal) cli.composicionCorporal = [];
  if (!cli.dolorAlicia) cli.dolorAlicia = {};
  if (cli.correo === undefined) cli.correo = "";
  if (!cli.categoria) cli.categoria = "";
  if (!cli.pilares) cli.pilares = { movimiento: "", sueno: "", nutricion: "", mindset: "", regeneracion: "" };
  if (cli.pilares.movimiento === undefined) cli.pilares.movimiento = "";
  return cli;
}

function useDipraData() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    (async () => {
      try {
        const res = await window.storage.get(STORAGE_KEY, true);
        if (res && res.value) {
          const parsed = JSON.parse(res.value);
          // backfill fields added after some users already had saved data
          if (!parsed.biblioteca) parsed.biblioteca = seedData().biblioteca;
          if (Array.isArray(parsed.clients)) parsed.clients = parsed.clients.map(migrarCliente);
          setData(parsed);
        } else {
          const seed = seedData();
          setData(seed);
          await window.storage.set(STORAGE_KEY, JSON.stringify(seed), true);
        }
      } catch (e) {
        setData(seedData());
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  const persist = useCallback(async (next) => {
    setData(next);
    setSaving(true);
    try {
      await window.storage.set(STORAGE_KEY, JSON.stringify(next), true);
    } catch (e) {
      /* best effort */
    } finally {
      setSaving(false);
    }
  }, []);

  // Para operaciones de "agregar" (cliente nuevo, cita nueva, ejercicio a la
  // biblioteca): relee lo último guardado antes de escribir, para no pisar
  // un cambio que otra persona acaba de guardar desde otra sesión.
  const persistMerge = useCallback(async (mergeFn) => {
    setSaving(true);
    try {
      const res = await window.storage.get(STORAGE_KEY, true);
      const latest = res && res.value ? JSON.parse(res.value) : data;
      const next = mergeFn(latest);
      setData(next);
      await window.storage.set(STORAGE_KEY, JSON.stringify(next), true);
    } catch (e) {
      /* best effort */
    } finally {
      setSaving(false);
    }
  }, [data]);

  return { data, setData: persist, persistMerge, loading, saving };
}

