/* ------------------------- Barra de carga (signature) ------------------------- */
/* Visualiza la carga semanal por día como una barra apilada por bloque —
   el mismo componente sirve para el profesional (planificación) y para
   el cliente (su propio progreso). */

function calcVolumenBloque(bloque) {
  return bloque.exercises.reduce((sum, e) => sum + (Number(e.series) || 0) * (Number(e.reps) || 0) * (Number(e.kg) || 0), 0);
}
function calcVolumenDia(dia) {
  return dia.bloques.reduce((sum, b) => sum + calcVolumenBloque(b), 0);
}

/* Vista de solo lectura de un día completo, para tener un "resumen de rutina"
   limpio fuera del modo edición — pensado para imprimir/mostrar rápido. */
function ResumenDia({ dia }) {
  const vol = calcVolumenDia(dia);
  return (
    <div className="bg-white rounded-2xl border dp-border-faint p-5">
      <div className="flex items-center justify-between mb-3">
        <div>
          <h3 className="font-semibold dp-ink" style={{ fontFamily: "'Space Grotesk', sans-serif" }}>{dia.label}</h3>
          {dia.foco && <p className="text-xs dp-muted">{dia.foco}</p>}
        </div>
        <span className="font-mono text-xs dp-muted">{vol.toLocaleString("es-CL")} kg vol. total</span>
      </div>
      <div className="space-y-4">
        {dia.bloques.map((b) => (
          <div key={b.id}>
            <p className="text-xs font-semibold dp-text-brand uppercase tracking-wide mb-1">{b.title}</p>
            {b.exercises.length === 0 ? (
              <p className="text-xs dp-muted">Sin ejercicios.</p>
            ) : (
              <div className="divide-y dp-divide-faint">
                {b.exercises.map((e) => (
                  <div key={e.id} className="flex items-center justify-between py-1.5 gap-3">
                    <div className="min-w-0">
                      {e.link ? (
                        <a href={e.link} target="_blank" rel="noreferrer" className="text-sm dp-text-brand underline truncate block">{e.nombre}</a>
                      ) : (
                        <span className="text-sm dp-ink truncate block">{e.nombre}</span>
                      )}
                      {e.comentarioCliente && <p className="text-[11px] dp-text-amber mt-0.5">"{e.comentarioCliente}"</p>}
                    </div>
                    <span className="font-mono text-xs dp-muted text-right shrink-0">
                      {e.series}×{e.reps}×{e.kg}kg
                      {e.rpe ? ` · RPE ${e.rpe}` : ""}{e.rir ? ` · RIR ${e.rir}` : ""}{e.tut ? ` · TUT ${e.tut}` : ""}{e.descanso ? ` · Desc. ${e.descanso}` : ""}
                    </span>
                  </div>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

function BarraDeCarga({ dias, compact = false }) {
  const volumenes = dias.map((d) => ({ label: d.label, total: calcVolumenDia(d), bloques: d.bloques.map((b) => ({ title: b.title, v: calcVolumenBloque(b) })) }));
  const max = Math.max(1, ...volumenes.map((v) => v.total));
  const blockTones = ["#1E8449", "#C9871D", "#4A534F", "#7FA79E"];

  return (
    <div className={`grid grid-cols-4 gap-3 ${compact ? "" : "mt-2"}`}>
      {volumenes.map((v, i) => (
        <div key={i} className="flex flex-col items-center gap-1.5">
          <div className="w-full h-28 dp-bg-faint rounded-lg overflow-hidden flex flex-col-reverse">
            {v.bloques.map((b, bi) => {
              const h = v.total > 0 ? (b.v / max) * 100 : 0;
              return b.v > 0 ? (
                <div
                  key={bi}
                  style={{ height: `${h}%`, background: blockTones[bi % blockTones.length] }}
                  title={`${b.title}: ${b.v.toLocaleString("es-CL")} kg`}
                />
              ) : null;
            })}
          </div>
          <span className="text-[11px] font-medium dp-body">{v.label}</span>
          <span className="font-mono text-xs font-semibold dp-ink">
            {v.total.toLocaleString("es-CL")} kg
          </span>
        </div>
      ))}
    </div>
  );
}

/* ------------------------------ Inicio ------------------------------ */

function Inicio({ data, onGoAgenda, onGoClient }) {
  const today = new Date();
  const fechaLabel = today.toLocaleDateString("es-CL", { weekday: "long", day: "numeric", month: "long" }).toUpperCase();
  const todayIso = today.toISOString().slice(0, 10);
  const citasHoy = data.appts.filter((a) => a.fecha === todayIso).sort((a, b) => a.hora.localeCompare(b.hora));
  const alertas = data.appts.filter((a) => a.estado === "alerta");

  return (
    <div className="space-y-6">
      <div>
        <p className="text-xs tracking-wide dp-muted font-medium">{fechaLabel}</p>
        <h1 className="mt-1" style={{ fontFamily: "'Space Grotesk', sans-serif" }}>
          <span className="text-3xl font-semibold dp-ink">Buenas, Nicolás.</span>
        </h1>
        <p className="dp-body mt-1">
          Tu jornada tiene {citasHoy.length} sesion{citasHoy.length === 1 ? "" : "es"}
          {alertas.length > 0 && <> · <span className="dp-alert font-medium">{alertas.length} con alerta de recuperación</span></>}.
        </p>
      </div>

      <div className="grid grid-cols-3 gap-4">
        <div className="bg-white rounded-2xl border dp-border-faint p-5">
          <p className="text-xs dp-muted font-medium">Clientes activos</p>
          <p className="text-3xl font-semibold mt-1" style={{ fontFamily: "'Space Grotesk', sans-serif" }}>{data.clients.length}</p>
        </div>
        <div className="bg-white rounded-2xl border dp-border-faint p-5">
          <p className="text-xs dp-muted font-medium">Sesiones hoy</p>
          <p className="text-3xl font-semibold mt-1" style={{ fontFamily: "'Space Grotesk', sans-serif" }}>{citasHoy.length}</p>
        </div>
        <div className="bg-white rounded-2xl border dp-border-faint p-5">
          <p className="text-xs dp-muted font-medium">Alertas de recuperación</p>
          <p className="text-3xl font-semibold mt-1 dp-alert" style={{ fontFamily: "'Space Grotesk', sans-serif" }}>{alertas.length}</p>
        </div>
      </div>

      <div className="bg-white rounded-2xl border dp-border-faint p-5">
        <div className="flex items-center justify-between mb-3">
          <h2 className="font-semibold dp-ink">Agenda de hoy</h2>
          <button onClick={onGoAgenda} className="text-sm dp-text-brand font-medium flex items-center gap-1 hover:underline">
            Ver agenda completa <ChevronRight size={15} />
          </button>
        </div>
        {citasHoy.length === 0 ? (
          <p className="text-sm dp-muted py-6 text-center">No hay sesiones agendadas para hoy. Ábrela desde Agenda para sumar una.</p>
        ) : (
          <div className="divide-y dp-divide-faint">
            {citasHoy.map((c) => (
              <button key={c.id} onClick={() => onGoClient(c.clienteId)} className="w-full flex items-center gap-3 py-3 text-left hover:bg-black/[0.02] -mx-2 px-2 rounded-lg">
                <span className="font-mono text-sm dp-body w-14">{c.hora}</span>
                <Avatar initials={c.cliente.split(" ").map((n) => n[0]).slice(0, 2).join("")} size={32} />
                <div className="flex-1">
                  <p className="text-sm font-medium dp-ink">{c.cliente}</p>
                  <p className="text-xs dp-muted">{c.tipo}</p>
                </div>
                <StatusPill estado={c.estado} />
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

