function Field({ label, value, onChange, readOnly, area }) {
  const Comp = area ? "textarea" : "input";
  return (
    <div>
      <label className="text-xs font-medium dp-muted">{label}</label>
      {readOnly ? (
        <p className="mt-1 text-sm dp-ink">{value || "—"}</p>
      ) : (
        <Comp
          value={value} onChange={(e) => onChange(e.target.value)}
          rows={area ? 2 : undefined}
          className="w-full mt-1 border dp-border-hairline rounded-lg px-3 py-1.5 text-sm outline-none dp-focus-brand"
        />
      )}
    </div>
  );
}

function FichaTab({ cliente, onUpdate, readOnly }) {
  const setField = (path, value) => {
    const next = structuredClone(cliente);
    let obj = next;
    for (let i = 0; i < path.length - 1; i++) obj = obj[path[i]];
    obj[path[path.length - 1]] = value;
    onUpdate(next);
  };

  const antecedentes = cliente.antecedentes || {};
  const camposExtra = cliente.camposExtra || [];

  const agregarCampoExtra = () => {
    const next = structuredClone(cliente);
    if (!next.camposExtra) next.camposExtra = [];
    next.camposExtra.push({ id: uid(), etiqueta: "", valor: "" });
    onUpdate(next);
  };
  const setCampoExtra = (id, patch) => {
    const next = structuredClone(cliente);
    next.camposExtra = (next.camposExtra || []).map((c) => (c.id === id ? { ...c, ...patch } : c));
    onUpdate(next);
  };
  const quitarCampoExtra = (id) => {
    const next = structuredClone(cliente);
    next.camposExtra = (next.camposExtra || []).filter((c) => c.id !== id);
    onUpdate(next);
  };

  return (
    <div className="grid grid-cols-2 gap-5">
      <div className="bg-white rounded-2xl border dp-border-faint p-5 space-y-3">
        <h3 className="font-semibold dp-ink flex items-center gap-2"><User size={16} /> Datos personales</h3>
        <Field label="Correo" value={cliente.correo} onChange={(v) => setField(["correo"], v)} readOnly={readOnly} />
        <Field label="Teléfono" value={cliente.telefono} onChange={(v) => setField(["telefono"], v)} readOnly={readOnly} />
        <Field label="Ocupación" value={cliente.ocupacion} onChange={(v) => setField(["ocupacion"], v)} readOnly={readOnly} />
        <Field label="Categoría" value={cliente.categoria} onChange={(v) => setField(["categoria"], v)} readOnly={readOnly} />
        <Field label="Inicio" value={cliente.inicio} onChange={(v) => setField(["inicio"], v)} readOnly={readOnly} />
        <Field label="Objetivo" value={cliente.objetivo} onChange={(v) => setField(["objetivo"], v)} readOnly={readOnly} area />

        <div className="pt-2 border-t dp-border-faint">
          <div className="flex items-center justify-between mb-1">
            <p className="text-xs font-semibold dp-ink uppercase tracking-wide">Datos adicionales</p>
            {!readOnly && (
              <button onClick={agregarCampoExtra} className="text-xs font-medium dp-text-brand hover:underline flex items-center gap-1">
                <Plus size={12} /> Agregar campo
              </button>
            )}
          </div>
          {camposExtra.length === 0 && <p className="text-xs dp-muted">Sin campos adicionales.</p>}
          {camposExtra.map((c) => (
            <div key={c.id} className="flex items-center gap-2 mb-1.5">
              {readOnly ? (
                <>
                  <span className="text-xs font-medium dp-muted" style={{ width: 110 }}>{c.etiqueta || "—"}</span>
                  <span className="text-sm dp-ink flex-1">{c.valor || "—"}</span>
                </>
              ) : (
                <>
                  <input value={c.etiqueta} onChange={(e) => setCampoExtra(c.id, { etiqueta: e.target.value })} placeholder="Nombre del dato"
                    className="text-xs border dp-border-hairline rounded-md px-2 py-1 outline-none dp-focus-brand" style={{ width: 110 }} />
                  <input value={c.valor} onChange={(e) => setCampoExtra(c.id, { valor: e.target.value })} placeholder="Valor"
                    className="text-sm border dp-border-hairline rounded-md px-2 py-1 outline-none dp-focus-brand flex-1" />
                  <button onClick={() => quitarCampoExtra(c.id)} className="dp-muted dp-hover-alert"><X size={13} /></button>
                </>
              )}
            </div>
          ))}
        </div>
      </div>

      <div className="bg-white rounded-2xl border dp-border-faint p-5 space-y-3">
        <h3 className="font-semibold dp-ink flex items-center gap-2"><Stethoscope size={16} /> Antecedentes clínicos</h3>
        <Field label="Antecedentes mórbidos" value={antecedentes.morbidos} onChange={(v) => setField(["antecedentes", "morbidos"], v)} readOnly={readOnly} area />
        <Field label="Cirugías (Qx)" value={antecedentes.qx} onChange={(v) => setField(["antecedentes", "qx"], v)} readOnly={readOnly} area />
        <Field label="Partos (si es mujer)" value={antecedentes.partos} onChange={(v) => setField(["antecedentes", "partos"], v)} readOnly={readOnly} area />
        <Field label="Tratamiento hormonal / menopausia / anticonceptivos" value={antecedentes.hormonal} onChange={(v) => setField(["antecedentes", "hormonal"], v)} readOnly={readOnly} area />
        <Field label="Enfermedades crónicas" value={antecedentes.cronicas} onChange={(v) => setField(["antecedentes", "cronicas"], v)} readOnly={readOnly} area />
        <Field label="Antecedentes respiratorios" value={antecedentes.respiratorios} onChange={(v) => setField(["antecedentes", "respiratorios"], v)} readOnly={readOnly} area />
        <Field label="Antecedentes sistémicos" value={antecedentes.sistemicos} onChange={(v) => setField(["antecedentes", "sistemicos"], v)} readOnly={readOnly} area />
        <Field label="Antecedentes neurológicos" value={antecedentes.neurologicos} onChange={(v) => setField(["antecedentes", "neurologicos"], v)} readOnly={readOnly} area />
        <Field label="Antecedentes cardíacos" value={antecedentes.cardiacos} onChange={(v) => setField(["antecedentes", "cardiacos"], v)} readOnly={readOnly} area />
        <Field label="Cáncer" value={antecedentes.cancer} onChange={(v) => setField(["antecedentes", "cancer"], v)} readOnly={readOnly} area />
        <Field label="Deporte que practica" value={antecedentes.deporte} onChange={(v) => setField(["antecedentes", "deporte"], v)} readOnly={readOnly} area />
        <Field label="Lesiones previas" value={antecedentes.lesiones} onChange={(v) => setField(["antecedentes", "lesiones"], v)} readOnly={readOnly} area />
      </div>
    </div>
  );
}

function ExerciseRow({ ex, onChange, onRemove, readOnly, biblioteca = [], onSaveToBiblioteca = () => {}, allowClientComment = false }) {
  const volumen = (Number(ex.series) || 0) * (Number(ex.reps) || 0) * (Number(ex.kg) || 0);
  const datalistId = "biblioteca-datalist";

  const handleNombreChange = (nombre) => {
    const match = biblioteca.find((b) => b.nombre.toLowerCase() === nombre.toLowerCase());
    if (match && !ex.link) {
      onChange({ ...ex, nombre, link: match.link });
    } else {
      onChange({ ...ex, nombre });
    }
  };

  const yaEnBiblioteca = biblioteca.some((b) => b.nombre.toLowerCase() === (ex.nombre || "").toLowerCase());
  const puedeGuardar = !readOnly && ex.nombre?.trim() && ex.link?.trim() && !yaEnBiblioteca;

  const buscarEnYoutube = () => {
    const q = encodeURIComponent(`${ex.nombre} ejercicio tecnica`);
    window.open(`https://www.youtube.com/results?search_query=${q}`, "_blank");
  };

  const campo = (key, label, width = 44) => (
    <div className="flex items-center gap-1">
      <span className="text-[10px] dp-muted font-medium">{label}</span>
      {readOnly ? (
        <span className="font-mono text-xs dp-body">{ex[key] || "—"}</span>
      ) : (
        <input
          value={ex[key] || ""} onChange={(e) => onChange({ ...ex, [key]: e.target.value })}
          style={{ width }}
          className="font-mono text-xs border dp-border-hairline rounded-md px-1 py-0.5 outline-none dp-focus-brand text-center"
        />
      )}
    </div>
  );

  return (
    <div className="py-1.5">
      <div className="grid items-center gap-2" style={{ gridTemplateColumns: "1.6fr 0.55fr 0.55fr 0.6fr 0.7fr auto" }}>
        {readOnly ? (
          <a href={ex.link || undefined} target="_blank" rel="noreferrer" className={`text-sm ${ex.link ? "dp-text-brand underline" : "dp-ink"}`}>
            {ex.nombre}
          </a>
        ) : (
          <input
            value={ex.nombre} onChange={(e) => handleNombreChange(e.target.value)}
            list={datalistId} placeholder="Ejercicio (sugiere desde la biblioteca)"
            className="text-sm border dp-border-hairline rounded-lg px-2 py-1 outline-none dp-focus-brand"
          />
        )}
        {["series", "reps", "kg"].map((k) => (
          readOnly ? (
            <span key={k} className="font-mono text-sm text-center dp-body">{ex[k]}</span>
          ) : (
            <input key={k} type="number" value={ex[k]} onChange={(e) => onChange({ ...ex, [k]: e.target.value })}
              className="font-mono text-sm border dp-border-hairline rounded-lg px-2 py-1 outline-none dp-focus-brand text-center" />
          )
        ))}
        <span className="font-mono text-xs dp-muted text-right">{volumen.toLocaleString("es-CL")} kg</span>
        {!readOnly && (
          <button onClick={onRemove} className="dp-muted dp-hover-alert"><X size={14} /></button>
        )}
      </div>

      <div className="flex items-center gap-3 mt-1" style={{ paddingLeft: 2 }}>
        {campo("rpe", "RPE")}
        {campo("rir", "RIR")}
        {campo("tut", "TUT")}
        {campo("descanso", "Desc.", 52)}
      </div>

      {!readOnly && (
        <div className="flex items-center gap-1.5 mt-1" style={{ paddingLeft: 2 }}>
          <Play size={11} className="dp-muted shrink-0" />
          <input
            value={ex.link || ""} onChange={(e) => onChange({ ...ex, link: e.target.value })}
            placeholder="Pega aquí el link del video (o búscalo en YouTube →)"
            className="flex-1 text-xs border-none outline-none dp-muted bg-transparent"
          />
          <button onClick={buscarEnYoutube} type="button" className="text-[11px] font-medium dp-text-brand hover:underline shrink-0 whitespace-nowrap">
            Buscar en YouTube
          </button>
          {puedeGuardar && (
            <button onClick={() => onSaveToBiblioteca({ id: uid(), nombre: ex.nombre.trim(), link: ex.link.trim() })}
              className="text-[11px] font-medium dp-text-amber hover:underline shrink-0 whitespace-nowrap">
              + Guardar en biblioteca
            </button>
          )}
        </div>
      )}

      {allowClientComment ? (
        <div className="flex items-center gap-1.5 mt-1 dp-bg-faint rounded-lg px-2 py-1" style={{ marginLeft: 2 }}>
          <ClipboardList size={12} className="dp-text-brand shrink-0" />
          <input
            value={ex.comentarioCliente || ""} onChange={(e) => onChange({ ...ex, comentarioCliente: e.target.value })}
            placeholder="Deja tu comentario — ej: no pude con 35, tiré 30 / me salieron 7 reps"
            className="flex-1 text-xs border-none outline-none dp-ink bg-transparent"
          />
        </div>
      ) : (
        readOnly && ex.comentarioCliente && (
          <div className="flex items-center gap-1.5 mt-1 dp-bg-faint rounded-lg px-2 py-1" style={{ marginLeft: 2 }}>
            <ClipboardList size={12} className="dp-text-amber shrink-0" />
            <span className="flex-1 text-xs dp-ink">{ex.comentarioCliente}</span>
          </div>
        )
      )}
    </div>
  );
}

/* Franja compacta con lo más importante del FMS, para tenerlo a la vista
   mientras se programa — sin tener que ir a la pestaña Evaluación. */
function FmsResumenPlan({ cliente }) {
  const [abierto, setAbierto] = useState(false);
  const fms = cliente.fms || emptyFms();
  const finals = calcularFinalesFms(fms);
  const total = Object.values(finals).reduce((sum, v) => sum + (typeof v === "number" ? v : 0), 0);
  const alertas = Object.entries(finals)
    .filter(([, score]) => score === 0 || score === 1 || score === 2)
    .sort((a, b) => a[1] - b[1]);

  const algunaEvaluada = Object.values(finals).some((v) => v !== null && v !== undefined);
  if (!algunaEvaluada) return null;

  return (
    <div className="bg-white rounded-2xl border dp-border-faint overflow-hidden">
      <button onClick={() => setAbierto((v) => !v)} className="w-full p-4 flex items-center gap-3">
        <Sparkles size={15} className="dp-text-brand shrink-0" />
        <span className="text-sm font-semibold dp-ink shrink-0">FMS: {total}<span className="dp-muted font-normal">/21</span></span>
        {alertas.length > 0 && (
          <span className="text-xs dp-muted">
            {alertas.length} movimiento{alertas.length > 1 ? "s" : ""} con restricción
          </span>
        )}
        <ChevronRight size={15} className={`dp-muted ml-auto transition-transform ${abierto ? "rotate-90" : ""}`} />
      </button>
      {abierto && (
        <div className="px-4 pb-4">
          {alertas.length === 0 ? (
            <span className="text-xs dp-muted">Sin restricciones marcadas en el screening.</span>
          ) : (
            <div className="flex items-center gap-1.5 flex-wrap">
              {alertas.map(([key, score]) => (
                <span key={key} title={FMS_SUGERENCIAS[key]?.[score]}
                  className={`text-xs font-medium px-2 py-0.5 rounded-full text-white ${score <= 1 ? "dp-bg-alert" : "dp-bg-amber"}`}>
                  {FMS_SUGERENCIAS[key]?.label || key} · {score}
                </span>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function PlanTab({ cliente, onUpdate, readOnly, biblioteca = [], onSaveToBiblioteca = () => {}, allowClientComment = false }) {
  const semanas = cliente.plan.semanas;
  const [semanaId, setSemanaId] = useState(cliente.plan.semanaActivaId || semanas[0]?.id);
  const semanaIdx = Math.max(0, semanas.findIndex((s) => s.id === semanaId));
  const semana = semanas[semanaIdx] || semanas[0];

  const [diaIdx, setDiaIdx] = useState(0);
  const dia = semana.dias[diaIdx];
  const [vista, setVista] = useState("editar"); // "editar" | "resumen-dia" | "resumen-semana"

  const updateSemana = (nextSemana) => {
    const next = structuredClone(cliente);
    next.plan.semanas[semanaIdx] = nextSemana;
    onUpdate(next);
  };
  const updateDia = (nextDia) => {
    const nextSemana = structuredClone(semana);
    nextSemana.dias[diaIdx] = nextDia;
    updateSemana(nextSemana);
  };

  const agregarSemana = () => {
    const nueva = nuevaSemana(semanas.length + 1, semana.mesociclo, semana.objetivo);
    // clona la estructura de bloques/ejercicios de la semana activa como punto de partida
    nueva.dias = structuredClone(semana.dias).map((d) => ({ ...d, id: uid() }));
    const next = structuredClone(cliente);
    next.plan.semanas.push(nueva);
    next.plan.semanaActivaId = nueva.id;
    onUpdate(next);
    setSemanaId(nueva.id);
    setDiaIdx(0);
  };

  const addExercise = (bIdx) => {
    const nextDia = structuredClone(dia);
    nextDia.bloques[bIdx].exercises.push({ id: uid(), nombre: "", series: 3, reps: 10, kg: 0, link: "", rpe: "", tut: "", rir: "", descanso: "", comentarioCliente: "" });
    updateDia(nextDia);
  };
  const changeExercise = (bIdx, eIdx, nextEx) => {
    const nextDia = structuredClone(dia);
    nextDia.bloques[bIdx].exercises[eIdx] = nextEx;
    updateDia(nextDia);
  };
  const removeExercise = (bIdx, eIdx) => {
    const nextDia = structuredClone(dia);
    nextDia.bloques[bIdx].exercises.splice(eIdx, 1);
    updateDia(nextDia);
  };
  const addBloque = () => {
    const nextDia = structuredClone(dia);
    nextDia.bloques.push({ id: uid(), title: "Nuevo bloque", exercises: [] });
    updateDia(nextDia);
  };
  const insertBloqueAfter = (bIdx) => {
    const nextDia = structuredClone(dia);
    nextDia.bloques.splice(bIdx + 1, 0, { id: uid(), title: "Nuevo bloque", exercises: [] });
    updateDia(nextDia);
  };
  const renameBloque = (bIdx, title) => {
    const nextDia = structuredClone(dia);
    nextDia.bloques[bIdx].title = title;
    updateDia(nextDia);
  };
  const removeBloque = (bIdx) => {
    const nextDia = structuredClone(dia);
    nextDia.bloques.splice(bIdx, 1);
    updateDia(nextDia);
  };

  return (
    <div className="space-y-5">
      <FmsResumenPlan cliente={cliente} />
      {!readOnly && (
        <datalist id="biblioteca-datalist">
          {biblioteca.map((b) => <option key={b.id} value={b.nombre} />)}
        </datalist>
      )}
      <div className="bg-white rounded-2xl border dp-border-faint p-5">
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-1.5 flex-wrap">
            {semanas.map((s) => (
              <button key={s.id} onClick={() => { setSemanaId(s.id); setDiaIdx(0); if (!readOnly) { const next = structuredClone(cliente); next.plan.semanaActivaId = s.id; onUpdate(next); } }}
                className={`px-2.5 py-1 rounded-lg text-xs font-medium transition-colors ${s.id === semana.id ? "dp-bg-brand text-white" : "dp-bg-faint dp-body"}`}>
                Semana {s.numero}
              </button>
            ))}
            {!readOnly && (
              <button onClick={agregarSemana} className="px-2.5 py-1 rounded-lg text-xs font-medium dp-text-brand border border-dashed dp-border-hairline">
                <Plus size={12} className="inline -mt-0.5" /> Nueva semana
              </button>
            )}
          </div>
        </div>
        <div className="grid grid-cols-2 gap-3 mb-4">
          {readOnly ? (
            <>
              <div><p className="text-[10px] dp-muted font-medium uppercase">Mesociclo</p><p className="text-sm dp-ink">{semana.mesociclo || "—"}</p></div>
              <div><p className="text-[10px] dp-muted font-medium uppercase">Objetivo de la fase</p><p className="text-sm dp-text-brand">{semana.objetivo || "—"}</p></div>
            </>
          ) : (
            <>
              <input value={semana.mesociclo || ""} onChange={(e) => updateSemana({ ...semana, mesociclo: e.target.value })} placeholder="Mesociclo (ej. Mesociclo 5)"
                className="text-sm border dp-border-hairline rounded-lg px-3 py-1.5 outline-none dp-focus-brand" />
              <input value={semana.objetivo || ""} onChange={(e) => updateSemana({ ...semana, objetivo: e.target.value })} placeholder="Objetivo de la fase (ej. Fuerza máxima)"
                className="text-sm border dp-border-hairline rounded-lg px-3 py-1.5 outline-none dp-focus-brand" />
            </>
          )}
        </div>
        <div className="flex items-center justify-between mb-1">
          <h3 className="font-semibold dp-ink flex items-center gap-2"><BarChart3 size={16} /> Carga semanal</h3>
        </div>
        <BarraDeCarga dias={semana.dias} />
      </div>

      <div className="flex items-center gap-1.5">
        {[
          { id: "editar", label: readOnly ? "Ver por día" : "Editar" },
          { id: "resumen-dia", label: "Resumen del día" },
          { id: "resumen-semana", label: "Resumen de la semana" },
        ].map((v) => (
          <button key={v.id} onClick={() => setVista(v.id)}
            className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${vista === v.id ? "dp-bg-brand text-white" : "dp-bg-faint dp-body"}`}>
            {v.label}
          </button>
        ))}
      </div>

      {vista === "resumen-semana" ? (
        <div className="space-y-4">
          {semana.dias.map((d) => <ResumenDia key={d.id} dia={d} />)}
        </div>
      ) : vista === "resumen-dia" ? (
        <>
          <div className="flex gap-1.5">
            {semana.dias.map((d, i) => (
              <button key={d.id} onClick={() => setDiaIdx(i)}
                className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${i === diaIdx ? "dp-bg-ink text-white" : "dp-bg-faint dp-body"}`}>
                {d.label}
              </button>
            ))}
          </div>
          <ResumenDia dia={dia} />
        </>
      ) : (
      <>
      <div className="flex gap-1.5">
        {semana.dias.map((d, i) => (
          <button key={d.id} onClick={() => setDiaIdx(i)}
            className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${i === diaIdx ? "dp-bg-ink text-white" : "dp-bg-faint dp-body"}`}>
            {d.label}
          </button>
        ))}
      </div>

      <div className="bg-white rounded-2xl border dp-border-faint p-5">
        {readOnly ? (
          <p className="text-sm dp-muted mb-3">{dia.foco || "Sin foco definido para este día."}</p>
        ) : (
          <input value={dia.foco} onChange={(e) => updateDia({ ...dia, foco: e.target.value })} placeholder="Foco del día (ej. Empuje superior / Tracción inferior)"
            className="w-full mb-4 text-sm border dp-border-hairline rounded-lg px-3 py-1.5 outline-none dp-focus-brand" />
        )}

        <div className="space-y-5">
          {dia.bloques.map((b, bIdx) => {
            const vol = calcVolumenBloque(b);
            return (
              <div key={b.id}>
                <div className="flex items-center justify-between mb-1.5">
                  {readOnly ? (
                    <h4 className="text-sm font-semibold dp-ink uppercase tracking-wide">{b.title}</h4>
                  ) : (
                    <input
                      value={b.title} onChange={(e) => renameBloque(bIdx, e.target.value)}
                      className="text-sm font-semibold dp-ink uppercase tracking-wide bg-transparent border-none outline-none focus:underline"
                      style={{ minWidth: 120 }}
                    />
                  )}
                  <div className="flex items-center gap-2">
                    <span className="font-mono text-xs dp-muted">{vol.toLocaleString("es-CL")} kg vol.</span>
                    {!readOnly && (
                      <button onClick={() => removeBloque(bIdx)} title="Eliminar bloque" className="dp-muted dp-hover-alert">
                        <Trash2 size={13} />
                      </button>
                    )}
                  </div>
                </div>
                {b.exercises.length > 0 && (
                  <div className="grid gap-2 pb-1 text-[10px] uppercase tracking-wide dp-muted font-medium" style={{ gridTemplateColumns: "1.6fr 0.55fr 0.55fr 0.6fr 0.7fr auto" }}>
                    <span>Ejercicio</span><span className="text-center">Ser.</span><span className="text-center">Rep.</span><span className="text-center">Kg</span><span className="text-right">Vol.</span><span />
                  </div>
                )}
                <div className="divide-y dp-divide-faint">
                  {b.exercises.map((ex, eIdx) => (
                    <ExerciseRow key={ex.id} ex={ex}
                      onChange={(nx) => changeExercise(bIdx, eIdx, nx)}
                      onRemove={() => removeExercise(bIdx, eIdx)}
                      readOnly={readOnly}
                      biblioteca={biblioteca}
                      onSaveToBiblioteca={onSaveToBiblioteca}
                      allowClientComment={allowClientComment} />
                  ))}
                </div>
                {!readOnly && (
                  <button onClick={() => addExercise(bIdx)} className="mt-2 flex items-center gap-1 text-xs font-medium dp-text-brand hover:underline">
                    <Plus size={13} /> Agregar ejercicio
                  </button>
                )}
                {readOnly && b.exercises.length === 0 && (
                  <p className="text-xs dp-muted py-2">Sin ejercicios cargados.</p>
                )}
                {!readOnly && (
                  <button onClick={() => insertBloqueAfter(bIdx)} className="w-full mt-3 py-1 flex items-center justify-center gap-1 text-[11px] font-medium dp-muted dp-hover-brand-text border-t border-dashed dp-border-hairline">
                    <Plus size={11} /> Insertar bloque aquí
                  </button>
                )}
              </div>
            );
          })}
        </div>
        {!readOnly && (
          <button onClick={addBloque} className="mt-5 flex items-center gap-1.5 text-sm font-medium dp-text-brand hover:underline">
            <Plus size={15} /> Agregar bloque
          </button>
        )}
      </div>
      </>
      )}
    </div>
  );
}

/* --------------------------------- FMS --------------------------------- */

function sideVal(raw, cleared) {
  if (cleared) return 0;
  return raw === "" || raw === undefined || raw === null ? null : Number(raw);
}
function finalScore(dRaw, iRaw, dCleared = false, iCleared = false) {
  const d = sideVal(dRaw, dCleared);
  const i = sideVal(iRaw, iCleared);
  if (d === null && i === null) return null;
  if (d === null) return i;
  if (i === null) return d;
  return Math.min(d, i);
}

function calcularFinalesFms(fms) {
  return {
    sentadilla: sideVal(fms.sentadilla, false),
    pasoValla: finalScore(fms.pasoValla.d, fms.pasoValla.i),
    estocada: finalScore(fms.estocada.d, fms.estocada.i),
    hombro: finalScore(fms.hombro.d, fms.hombro.i, fms.clearingHombro.d, fms.clearingHombro.i),
    aslr: finalScore(fms.aslr.d, fms.aslr.i),
    pushUp: sideVal(fms.pushUp, fms.clearingExtension),
    rotacion: finalScore(fms.rotacion.d, fms.rotacion.i, fms.clearingFlexion, fms.clearingFlexion),
  };
}

function ClearingToggle({ value, onChange }) {
  return (
    <div className="flex rounded-md overflow-hidden border dp-border-hairline text-[11px] font-medium w-fit">
      <button onClick={() => onChange(false)} className={`px-2 py-0.5 ${!value ? "dp-bg-brand text-white" : "bg-white dp-muted"}`}>neg</button>
      <button onClick={() => onChange(true)} className={`px-2 py-0.5 ${value ? "dp-bg-alert text-white" : "bg-white dp-muted"}`}>pos</button>
    </div>
  );
}

function RawInput({ value, onChange, readOnly, width = 44 }) {
  if (readOnly) return <span className="font-mono text-sm dp-ink">{value === "" || value === undefined ? "—" : value}</span>;
  return (
    <input
      type="number" min="0" max="3" value={value}
      onChange={(e) => onChange(e.target.value)}
      style={{ width }}
      className="font-mono text-sm text-center border dp-border-hairline rounded-md px-1 py-0.5 outline-none dp-focus-brand"
    />
  );
}

function FmsRow({ label, dValue, iValue, onD, onI, final, single, singleValue, onSingle, readOnly }) {
  return (
    <div className="grid items-center gap-2 py-1.5 border-b dp-border-faint" style={{ gridTemplateColumns: "1.4fr 0.3fr 0.6fr 0.6fr" }}>
      <span className="text-sm dp-ink">{label}</span>
      {single ? (
        <>
          <span />
          <RawInput value={singleValue} onChange={onSingle} readOnly={readOnly} />
        </>
      ) : (
        <>
          <div className="flex flex-col gap-1 text-[10px] dp-muted font-medium">
            <span>D</span><span>I</span>
          </div>
          <div className="flex flex-col gap-1">
            <RawInput value={dValue} onChange={onD} readOnly={readOnly} width={36} />
            <RawInput value={iValue} onChange={onI} readOnly={readOnly} width={36} />
          </div>
        </>
      )}
      <span className={`font-mono text-sm text-center font-semibold rounded-md py-0.5 ${final === 0 || final === 1 ? "dp-bg-alert text-white" : final === 2 ? "dp-bg-amber text-white" : final !== null && final !== undefined ? "dp-bg-faint dp-ink" : "dp-muted"}`}>
        {final === null || final === undefined ? "—" : final}
      </span>
    </div>
  );
}

function FmsTab({ cliente, onUpdate, readOnly }) {
  const fms = cliente.fms || emptyFms();

  const setFms = (patch) => {
    const next = structuredClone(cliente);
    next.fms = { ...next.fms, ...patch };
    onUpdate(next);
  };
  const setNested = (key, side, value) => {
    const next = structuredClone(cliente);
    next.fms[key] = { ...next.fms[key], [side]: value };
    onUpdate(next);
  };

  const finals = calcularFinalesFms(fms);

  const total = Object.values(finals).reduce((sum, v) => sum + (typeof v === "number" ? v : 0), 0);

  const sugerencias = Object.entries(finals)
    .filter(([, score]) => score === 0 || score === 1 || score === 2)
    .sort((a, b) => a[1] - b[1])
    .map(([key, score]) => ({ key, score, ...FMS_SUGERENCIAS[key] }));

  const setSeguimiento = (key, texto) => {
    const next = structuredClone(cliente);
    if (!next.fms.seguimientoPropio) next.fms.seguimientoPropio = {};
    next.fms.seguimientoPropio[key] = texto;
    onUpdate(next);
  };

  return (
    <div className="grid grid-cols-2 gap-5">
      <div className="bg-white rounded-2xl border dp-border-faint p-5">
        <div className="flex items-center justify-between mb-3">
          <h3 className="font-semibold dp-ink">Screening de movimiento · FMS</h3>
          <div className="text-right">
            <p className="text-[10px] dp-muted font-medium uppercase tracking-wide">Total score</p>
            <p className="font-mono text-xl font-semibold dp-ink">{total}<span className="text-xs dp-muted"> / 21</span></p>
          </div>
        </div>

        <div className="grid gap-1 text-[10px] uppercase tracking-wide dp-muted font-medium pb-1" style={{ gridTemplateColumns: "1.4fr 0.3fr 0.6fr 0.6fr" }}>
          <span>Movimiento</span><span /><span>Raw</span><span className="text-center">Final</span>
        </div>

        <FmsRow label="Sentadilla" single singleValue={fms.sentadilla} onSingle={(v) => setFms({ sentadilla: v })} final={finals.sentadilla} readOnly={readOnly} />
        <FmsRow label="Paso valla" dValue={fms.pasoValla.d} iValue={fms.pasoValla.i} onD={(v) => setNested("pasoValla", "d", v)} onI={(v) => setNested("pasoValla", "i", v)} final={finals.pasoValla} readOnly={readOnly} />
        <FmsRow label="Estocada" dValue={fms.estocada.d} iValue={fms.estocada.i} onD={(v) => setNested("estocada", "d", v)} onI={(v) => setNested("estocada", "i", v)} final={finals.estocada} readOnly={readOnly} />

        <div className="flex items-center justify-between py-1.5 border-b dp-border-faint">
          <span className="text-xs dp-muted">Clearing tobillo · dolor</span>
          <div className="flex gap-2">
            {!readOnly ? (<><ClearingToggle value={fms.clearingTobDolor.d} onChange={(v) => setNested("clearingTobDolor", "d", v)} /><ClearingToggle value={fms.clearingTobDolor.i} onChange={(v) => setNested("clearingTobDolor", "i", v)} /></>) : (
              <span className="text-xs font-mono">{fms.clearingTobDolor.d ? "pos" : "neg"} / {fms.clearingTobDolor.i ? "pos" : "neg"}</span>
            )}
          </div>
        </div>

        <FmsRow label="Movilidad de hombro" dValue={fms.hombro.d} iValue={fms.hombro.i} onD={(v) => setNested("hombro", "d", v)} onI={(v) => setNested("hombro", "i", v)} final={finals.hombro} readOnly={readOnly} />
        <div className="flex items-center justify-between py-1.5 border-b dp-border-faint">
          <span className="text-xs dp-muted">Clearing hombro</span>
          <div className="flex gap-2">
            {!readOnly ? (<><ClearingToggle value={fms.clearingHombro.d} onChange={(v) => setNested("clearingHombro", "d", v)} /><ClearingToggle value={fms.clearingHombro.i} onChange={(v) => setNested("clearingHombro", "i", v)} /></>) : (
              <span className="text-xs font-mono">{fms.clearingHombro.d ? "pos" : "neg"} / {fms.clearingHombro.i ? "pos" : "neg"}</span>
            )}
          </div>
        </div>

        <FmsRow label="ASLR" dValue={fms.aslr.d} iValue={fms.aslr.i} onD={(v) => setNested("aslr", "d", v)} onI={(v) => setNested("aslr", "i", v)} final={finals.aslr} readOnly={readOnly} />
        <FmsRow label="Push up" single singleValue={fms.pushUp} onSingle={(v) => setFms({ pushUp: v })} final={finals.pushUp} readOnly={readOnly} />
        <div className="flex items-center justify-between py-1.5 border-b dp-border-faint">
          <span className="text-xs dp-muted">Clearing extensión</span>
          {!readOnly ? <ClearingToggle value={fms.clearingExtension} onChange={(v) => setFms({ clearingExtension: v })} /> : <span className="text-xs font-mono">{fms.clearingExtension ? "pos" : "neg"}</span>}
        </div>

        <FmsRow label="Estabilidad rotacional" dValue={fms.rotacion.d} iValue={fms.rotacion.i} onD={(v) => setNested("rotacion", "d", v)} onI={(v) => setNested("rotacion", "i", v)} final={finals.rotacion} readOnly={readOnly} />
        <div className="flex items-center justify-between py-1.5 border-b dp-border-faint">
          <span className="text-xs dp-muted">Clearing flexión</span>
          {!readOnly ? <ClearingToggle value={fms.clearingFlexion} onChange={(v) => setFms({ clearingFlexion: v })} /> : <span className="text-xs font-mono">{fms.clearingFlexion ? "pos" : "neg"}</span>}
        </div>

        <div className="flex items-center justify-between py-1.5 border-b dp-border-faint">
          <span className="text-xs dp-muted">Toe touch (cm)</span>
          <RawInput value={fms.toeTouch} onChange={(v) => setFms({ toeTouch: v })} readOnly={readOnly} width={50} />
        </div>
        <div className="flex items-center justify-between py-1.5">
          <span className="text-xs dp-muted">Clearing muñeca (der / izq)</span>
          <div className="flex gap-2">
            {!readOnly ? (<><ClearingToggle value={fms.clearingMuneca.der} onChange={(v) => setNested("clearingMuneca", "der", v)} /><ClearingToggle value={fms.clearingMuneca.izq} onChange={(v) => setNested("clearingMuneca", "izq", v)} /></>) : (
              <span className="text-xs font-mono">{fms.clearingMuneca.der ? "pos" : "neg"} / {fms.clearingMuneca.izq ? "pos" : "neg"}</span>
            )}
          </div>
        </div>
      </div>

      <div>
        <div className="bg-white rounded-2xl border dp-border-faint p-5 sticky" style={{ top: 20 }}>
          <h3 className="font-semibold dp-ink mb-1 flex items-center gap-2"><Sparkles size={16} className="dp-text-amber" /> Sugerencias de evaluación</h3>
          <p className="text-xs dp-muted mb-4">Se actualizan solas con puntajes 0, 1 o 2 — el 0 significa dolor y es lo más urgente, luego 1 y luego 2.</p>
          {sugerencias.length === 0 ? (
            <p className="text-sm dp-muted py-6 text-center">Sin puntajes de 0, 1 o 2 todavía. A medida que llenes el screening, aquí aparecerán los tests de seguimiento recomendados.</p>
          ) : (
            <div className="space-y-3">
              {sugerencias.map((s) => (
                <div key={s.key} className="rounded-xl p-3 dp-bg-faint">
                  <div className="flex items-center gap-2 mb-1">
                    <span className={`font-mono text-xs font-semibold text-white rounded-full w-5 h-5 flex items-center justify-center ${s.score <= 1 ? "dp-bg-alert" : "dp-bg-amber"}`}>{s.score}</span>
                    <span className="text-sm font-medium dp-ink">{s.label}</span>
                  </div>
                  <p className="text-xs dp-body leading-relaxed">{s[s.score]}</p>
                  <div className="mt-2">
                    <label className="text-[10px] font-medium dp-muted uppercase tracking-wide">Tu seguimiento (criterio propio)</label>
                    {readOnly ? (
                      <p className="text-xs dp-ink mt-0.5">{fms.seguimientoPropio?.[s.key] || "—"}</p>
                    ) : (
                      <input
                        value={fms.seguimientoPropio?.[s.key] || ""} onChange={(e) => setSeguimiento(s.key, e.target.value)}
                        placeholder="Ej: test de knee-to-wall, up and go, etc."
                        className="w-full mt-0.5 text-xs bg-white border dp-border-hairline rounded-md px-2 py-1 outline-none dp-focus-brand"
                      />
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/* -------------------------------- Sesiones -------------------------------- */

function SesionesTab({ cliente, onUpdate, readOnly }) {
  const semanaActiva = cliente.plan.semanas.find((s) => s.id === cliente.plan.semanaActivaId) || cliente.plan.semanas[0];
  const [modo, setModo] = useState("list");
  const [form, setForm] = useState(null);
  const [expandedId, setExpandedId] = useState(null);

  const sesiones = [...(cliente.sesiones || [])].sort((a, b) => b.fecha.localeCompare(a.fecha));

  const tieneAlerta = (s) =>
    !s.esPrimeraSesion &&
    PILARES_KEYS.some((p) => {
      const v = Number(s.pilares[p.key]);
      return s.pilares[p.key] !== "" && !isNaN(v) && tonoEscalaPilar(v, p.invertido) === "dp-bg-alert";
    });

  const iniciarNueva = () => {
    setForm(emptySesion((cliente.sesiones || []).length === 0));
    setModo("form");
  };

  const elegirDia = (label) => {
    const dia = semanaActiva.dias.find((d) => d.label === label);
    const ejercicios = [];
    if (dia) {
      dia.bloques.forEach((b) =>
        b.exercises.forEach((e) => {
          ejercicios.push({
            id: uid(), nombre: e.nombre,
            seriesPlan: e.series, repsPlan: e.reps, kgPlan: e.kg,
            seriesReal: e.series, repsReal: e.reps, kgReal: e.kg, rpe: "",
          });
        })
      );
    }
    setForm({ ...form, diaPlanLabel: label, ejercicios });
  };

  const updateEjercicio = (idx, patch) => {
    const next = [...form.ejercicios];
    next[idx] = { ...next[idx], ...patch };
    setForm({ ...form, ejercicios: next });
  };

  const guardar = () => {
    const next = structuredClone(cliente);
    next.sesiones = [form, ...(next.sesiones || [])];
    onUpdate(next);
    setForm(null);
    setModo("list");
  };

  const eliminarSesion = (id) => {
    const next = structuredClone(cliente);
    next.sesiones = (next.sesiones || []).filter((s) => s.id !== id);
    onUpdate(next);
  };

  if (modo === "form" && form) {
    return (
      <div className="bg-white rounded-2xl border dp-border-faint p-5 space-y-4">
        <div className="flex items-center justify-between">
          <h3 className="font-semibold dp-ink">Nueva sesión</h3>
          <button onClick={() => { setForm(null); setModo("list"); }} className="text-sm dp-muted dp-hover-ink">Cancelar</button>
        </div>

        <div className="grid grid-cols-3 gap-3">
          <div>
            <label className="text-xs font-medium dp-body">Fecha</label>
            <input type="date" value={form.fecha} onChange={(e) => setForm({ ...form, fecha: e.target.value })}
              className="w-full mt-1 border dp-border-hairline rounded-lg px-3 py-2 text-sm outline-none dp-focus-brand" />
          </div>
          <div>
            <label className="text-xs font-medium dp-body">Tipo de sesión</label>
            <select value={form.tipo} onChange={(e) => setForm({ ...form, tipo: e.target.value })}
              className="w-full mt-1 border dp-border-hairline rounded-lg px-3 py-2 text-sm outline-none dp-focus-brand">
              {TIPOS_SESION.map((t) => <option key={t} value={t}>{t}</option>)}
            </select>
          </div>
          <div>
            <label className="text-xs font-medium dp-body">Día del plan</label>
            <select value={form.diaPlanLabel} onChange={(e) => elegirDia(e.target.value)}
              className="w-full mt-1 border dp-border-hairline rounded-lg px-3 py-2 text-sm outline-none dp-focus-brand">
              <option value="">Selecciona…</option>
              {semanaActiva.dias.map((d) => <option key={d.id} value={d.label}>{d.label}{d.foco ? ` — ${d.foco}` : ""}</option>)}
            </select>
          </div>
        </div>

        <label className="flex items-center gap-2 text-sm dp-body">
          <input type="checkbox" checked={form.esPrimeraSesion} onChange={(e) => setForm({ ...form, esPrimeraSesion: e.target.checked })} />
          Es la primera sesión con este cliente
        </label>

        <div>
          <label className="text-xs font-medium dp-body">Comentarios pre-sesión — cómo llega la persona</label>
          <textarea rows={2} value={form.comentariosPre} onChange={(e) => setForm({ ...form, comentariosPre: e.target.value })}
            className="w-full mt-1 border dp-border-hairline rounded-lg px-3 py-2 text-sm outline-none dp-focus-brand" placeholder="Cómo se siente hoy, energía, dolores previos, ánimo…" />
        </div>

        <div>
          <p className="text-xs font-semibold dp-ink uppercase tracking-wide mb-2">Pilares del rendimiento — hoy</p>
          {form.esPrimeraSesion ? (
            <div className="grid grid-cols-2 gap-3">
              {PILARES_KEYS.map((p) => (
                <div key={p.key}>
                  <label className="text-xs font-medium dp-body">{p.label}</label>
                  <textarea rows={2} value={form.pilares[p.key]} onChange={(e) => setForm({ ...form, pilares: { ...form.pilares, [p.key]: e.target.value } })}
                    className="w-full mt-1 border dp-border-hairline rounded-lg px-3 py-1.5 text-sm outline-none dp-focus-brand" placeholder="Cómo lo describe el cliente…" />
                </div>
              ))}
            </div>
          ) : (
            <div className="space-y-2.5">
              {PILARES_KEYS.map((p) => (
                <div key={p.key} className="flex items-center gap-3">
                  <span className="text-xs font-medium dp-body" style={{ width: 84 }}>{p.label}</span>
                  <EscalaUnoADiez value={form.pilares[p.key]} onChange={(v) => setForm({ ...form, pilares: { ...form.pilares, [p.key]: v } })} invertido={p.invertido} />
                  <span className="font-mono text-xs dp-muted">{form.pilares[p.key] || "—"}/10</span>
                </div>
              ))}
            </div>
          )}
          {!form.esPrimeraSesion && PILARES_KEYS.some((p) => { const v = Number(form.pilares[p.key]); return form.pilares[p.key] !== "" && !isNaN(v) && tonoEscalaPilar(v, p.invertido) === "dp-bg-alert"; }) && (
            <p className="text-xs dp-alert mt-2 flex items-center gap-1"><AlertTriangle size={13} /> Hay al menos un pilar en rojo — revisar antes de cargar intensidad.</p>
          )}
        </div>

        {form.diaPlanLabel && (
          <div>
            <p className="text-xs font-semibold dp-ink uppercase tracking-wide mb-2">Ejecución real vs. planificado</p>
            <div className="grid gap-2 text-[10px] uppercase tracking-wide dp-muted font-medium pb-1" style={{ gridTemplateColumns: "1.4fr 0.9fr 0.5fr 0.5fr 0.5fr 0.4fr" }}>
              <span>Ejercicio</span><span>Plan (S×R×Kg)</span><span className="text-center">Ser.</span><span className="text-center">Rep.</span><span className="text-center">Kg</span><span className="text-center">RPE</span>
            </div>
            <div className="divide-y dp-divide-faint">
              {form.ejercicios.map((ex, idx) => (
                <div key={ex.id} className="grid items-center gap-2 py-1.5" style={{ gridTemplateColumns: "1.4fr 0.9fr 0.5fr 0.5fr 0.5fr 0.4fr" }}>
                  <span className="text-sm dp-ink">{ex.nombre}</span>
                  <span className="font-mono text-xs dp-muted">{ex.seriesPlan}×{ex.repsPlan}×{ex.kgPlan}kg</span>
                  <input type="number" value={ex.seriesReal} onChange={(e) => updateEjercicio(idx, { seriesReal: e.target.value })} className="font-mono text-sm text-center border dp-border-hairline rounded-md px-1 py-0.5 outline-none dp-focus-brand" />
                  <input type="number" value={ex.repsReal} onChange={(e) => updateEjercicio(idx, { repsReal: e.target.value })} className="font-mono text-sm text-center border dp-border-hairline rounded-md px-1 py-0.5 outline-none dp-focus-brand" />
                  <input type="number" value={ex.kgReal} onChange={(e) => updateEjercicio(idx, { kgReal: e.target.value })} className="font-mono text-sm text-center border dp-border-hairline rounded-md px-1 py-0.5 outline-none dp-focus-brand" />
                  <input type="number" min="0" max="10" value={ex.rpe} onChange={(e) => updateEjercicio(idx, { rpe: e.target.value })} placeholder="—" className="font-mono text-sm text-center border dp-border-hairline rounded-md px-1 py-0.5 outline-none dp-focus-brand" />
                </div>
              ))}
              {form.ejercicios.length === 0 && <p className="text-xs dp-muted py-2">Este día no tiene ejercicios cargados en la planificación todavía.</p>}
            </div>
          </div>
        )}

        <div>
          <label className="text-xs font-medium dp-body">Comentarios post sesión — dolor · dificultad · ajuste de carga</label>
          <textarea rows={3} value={form.comentarios} onChange={(e) => setForm({ ...form, comentarios: e.target.value })}
            className="w-full mt-1 border dp-border-hairline rounded-lg px-3 py-2 text-sm outline-none dp-focus-brand" />
        </div>

        <button onClick={guardar} className="dp-bg-brand text-white font-medium px-4 py-2 rounded-xl dp-hover-brand-dark transition-colors flex items-center gap-1.5">
          <Save size={15} /> Guardar sesión
        </button>
      </div>
    );
  }

  return (
    <div>
      {!readOnly && (
        <button onClick={iniciarNueva} className="flex items-center gap-1.5 dp-bg-brand text-white text-sm font-medium px-3.5 py-2 rounded-xl dp-hover-brand-dark transition-colors mb-4">
          <Plus size={16} /> Nueva sesión
        </button>
      )}
      {sesiones.length === 0 ? (
        <p className="text-sm dp-muted bg-white rounded-2xl border dp-border-faint p-8 text-center">Todavía no hay sesiones registradas para este cliente.</p>
      ) : (
        <div className="space-y-3">
          {sesiones.map((s) => {
            const expanded = expandedId === s.id;
            const alerta = tieneAlerta(s);
            return (
              <div key={s.id} className="bg-white rounded-2xl border dp-border-faint overflow-hidden">
                <button onClick={() => setExpandedId(expanded ? null : s.id)} className="w-full flex items-center gap-3 p-4 text-left">
                  <div className="text-center shrink-0" style={{ width: 56 }}>
                    <p className="font-mono text-sm font-semibold dp-ink">{s.fecha.slice(8, 10)}/{s.fecha.slice(5, 7)}</p>
                    <p className="text-[10px] dp-muted">{s.fecha.slice(0, 4)}</p>
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium dp-ink">{s.tipo || "Kinesiología"}{s.diaPlanLabel ? ` · ${s.diaPlanLabel}` : ""}</p>
                    <p className="text-xs dp-muted truncate">{s.comentarios || "Sin comentarios"}</p>
                  </div>
                  {alerta && (
                    <span className="flex items-center gap-1 text-xs font-medium dp-alert shrink-0">
                      <AlertTriangle size={13} /> Pilar bajo
                    </span>
                  )}
                  <ChevronRight size={16} className={`dp-muted shrink-0 transition-transform ${expanded ? "rotate-90" : ""}`} />
                </button>
                {expanded && (
                  <div className="px-4 pb-4 space-y-3 border-t dp-border-faint pt-3">
                    <div className="grid grid-cols-5 gap-2">
                      {PILARES_KEYS.map((p) => {
                        const val = s.pilares[p.key];
                        const numerico = !s.esPrimeraSesion && val !== "" && !isNaN(Number(val));
                        const tono = numerico ? tonoEscalaPilar(Number(val), p.invertido) : "dp-bg-faint";
                        const esColor = numerico;
                        return (
                          <div key={p.key} className={`rounded-lg p-2 text-center ${tono}`}>
                            <p className={`text-[10px] font-medium ${esColor ? "text-white/80" : "dp-muted"}`}>{p.label}</p>
                            <p className={`text-sm font-mono font-semibold ${esColor ? "text-white" : "dp-ink"}`}>{val || "—"}</p>
                          </div>
                        );
                      })}
                    </div>
                    {s.comentariosPre && (
                      <div>
                        <p className="text-[10px] font-medium dp-muted uppercase tracking-wide mb-0.5">Pre-sesión</p>
                        <p className="text-sm dp-ink">{s.comentariosPre}</p>
                      </div>
                    )}
                    {s.ejercicios.length > 0 && (
                      <div className="divide-y dp-divide-faint">
                        {s.ejercicios.map((ex) => (
                          <div key={ex.id} className="flex items-center justify-between py-1.5 text-sm">
                            <span className="dp-ink">{ex.nombre}</span>
                            <span className="font-mono text-xs dp-muted">
                              plan {ex.seriesPlan}×{ex.repsPlan}×{ex.kgPlan}kg → real {ex.seriesReal}×{ex.repsReal}×{ex.kgReal}kg{ex.rpe ? ` · RPE ${ex.rpe}` : ""}
                            </span>
                          </div>
                        ))}
                      </div>
                    )}
                    {!readOnly && (
                      <button onClick={() => eliminarSesion(s.id)} className="text-xs dp-alert hover:underline flex items-center gap-1">
                        <Trash2 size={12} /> Eliminar sesión
                      </button>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

/* ----------------------------- Evaluación ----------------------------- */

function PilaresSection({ cliente, onUpdate, readOnly }) {
  const setField = (path, value) => {
    const next = structuredClone(cliente);
    let obj = next;
    for (let i = 0; i < path.length - 1; i++) obj = obj[path[i]];
    obj[path[path.length - 1]] = value;
    onUpdate(next);
  };
  return (
    <div className="bg-white rounded-2xl border dp-border-faint p-5 space-y-3">
      <h3 className="font-semibold dp-ink flex items-center gap-2"><Stethoscope size={16} /> Pilares del rendimiento</h3>
      <Field label="Movimiento" value={cliente.pilares.movimiento} onChange={(v) => setField(["pilares", "movimiento"], v)} readOnly={readOnly} area />
      <Field label="Sueño / regeneración" value={cliente.pilares.regeneracion} onChange={(v) => setField(["pilares", "regeneracion"], v)} readOnly={readOnly} area />
      <Field label="Nutrición" value={cliente.pilares.nutricion} onChange={(v) => setField(["pilares", "nutricion"], v)} readOnly={readOnly} area />
      <Field label="Mindset" value={cliente.pilares.mindset} onChange={(v) => setField(["pilares", "mindset"], v)} readOnly={readOnly} area />
    </div>
  );
}

const ESFERAS = ["Cráneo", "Tórax", "Pelvis", "Tobillo"];

function ComposicionCorporalSection({ cliente, onUpdate, readOnly }) {
  const hist = [...(cliente.composicionCorporal || [])].sort((a, b) => b.fecha.localeCompare(a.fecha));
  const [showAdd, setShowAdd] = useState(false);
  const [draft, setDraft] = useState({ fecha: new Date().toISOString().slice(0, 10), talla: "", peso: "", grasaPct: "", masaMuscular: "", aguaPct: "", masaOsea: "" });

  const agregar = () => {
    if (!draft.talla && !draft.peso) return;
    const next = structuredClone(cliente);
    if (!next.composicionCorporal) next.composicionCorporal = [];
    next.composicionCorporal.push({
      id: uid(), fecha: draft.fecha,
      talla: Number(draft.talla) || 0, peso: Number(draft.peso) || 0,
      grasaPct: draft.grasaPct === "" ? "" : Number(draft.grasaPct),
      masaMuscular: draft.masaMuscular === "" ? "" : Number(draft.masaMuscular),
      aguaPct: draft.aguaPct === "" ? "" : Number(draft.aguaPct),
      masaOsea: draft.masaOsea === "" ? "" : Number(draft.masaOsea),
    });
    onUpdate(next);
    setDraft({ fecha: new Date().toISOString().slice(0, 10), talla: "", peso: "", grasaPct: "", masaMuscular: "", aguaPct: "", masaOsea: "" });
    setShowAdd(false);
  };

  const eliminar = (id) => {
    const next = structuredClone(cliente);
    next.composicionCorporal = (next.composicionCorporal || []).filter((c) => c.id !== id);
    onUpdate(next);
  };

  const imc = (t, p) => (t && p ? (p / ((t / 100) * (t / 100))).toFixed(1) : "—");

  return (
    <div className="bg-white rounded-2xl border dp-border-faint p-5">
      <div className="flex items-center justify-between mb-1">
        <h3 className="font-semibold dp-ink flex items-center gap-2"><User size={16} /> Composición corporal</h3>
        {!readOnly && (
          <button onClick={() => setShowAdd((v) => !v)} className="text-xs font-medium dp-text-brand hover:underline flex items-center gap-1">
            <Plus size={13} /> Agregar medición
          </button>
        )}
      </div>
      <p className="text-xs dp-muted mb-3">Talla, peso e IMC siempre; % grasa, masa muscular, % agua y masa ósea si tienes los datos (ej. balanza Body Pro).</p>

      {showAdd && (
        <div className="dp-bg-faint rounded-xl p-3 mb-3 grid grid-cols-4 gap-2">
          <div>
            <label className="text-[11px] font-medium dp-body">Fecha</label>
            <input type="date" value={draft.fecha} onChange={(e) => setDraft({ ...draft, fecha: e.target.value })} className="w-full mt-1 text-sm border dp-border-hairline rounded-md px-2 py-1 outline-none dp-focus-brand bg-white" />
          </div>
          <div>
            <label className="text-[11px] font-medium dp-body">Talla (cm)</label>
            <input type="number" value={draft.talla} onChange={(e) => setDraft({ ...draft, talla: e.target.value })} className="w-full mt-1 text-sm border dp-border-hairline rounded-md px-2 py-1 outline-none dp-focus-brand font-mono bg-white" />
          </div>
          <div>
            <label className="text-[11px] font-medium dp-body">Peso (kg)</label>
            <input type="number" value={draft.peso} onChange={(e) => setDraft({ ...draft, peso: e.target.value })} className="w-full mt-1 text-sm border dp-border-hairline rounded-md px-2 py-1 outline-none dp-focus-brand font-mono bg-white" />
          </div>
          <div>
            <label className="text-[11px] font-medium dp-body">% Grasa</label>
            <input type="number" value={draft.grasaPct} onChange={(e) => setDraft({ ...draft, grasaPct: e.target.value })} className="w-full mt-1 text-sm border dp-border-hairline rounded-md px-2 py-1 outline-none dp-focus-brand font-mono bg-white" />
          </div>
          <div>
            <label className="text-[11px] font-medium dp-body">Masa muscular (kg)</label>
            <input type="number" value={draft.masaMuscular} onChange={(e) => setDraft({ ...draft, masaMuscular: e.target.value })} className="w-full mt-1 text-sm border dp-border-hairline rounded-md px-2 py-1 outline-none dp-focus-brand font-mono bg-white" />
          </div>
          <div>
            <label className="text-[11px] font-medium dp-body">% Agua</label>
            <input type="number" value={draft.aguaPct} onChange={(e) => setDraft({ ...draft, aguaPct: e.target.value })} className="w-full mt-1 text-sm border dp-border-hairline rounded-md px-2 py-1 outline-none dp-focus-brand font-mono bg-white" />
          </div>
          <div>
            <label className="text-[11px] font-medium dp-body">Masa ósea (kg)</label>
            <input type="number" value={draft.masaOsea} onChange={(e) => setDraft({ ...draft, masaOsea: e.target.value })} className="w-full mt-1 text-sm border dp-border-hairline rounded-md px-2 py-1 outline-none dp-focus-brand font-mono bg-white" />
          </div>
          <div className="flex items-end">
            <button onClick={agregar} className="dp-bg-brand text-white text-sm font-medium px-3 py-1.5 rounded-md dp-hover-brand-dark transition-colors w-full">Guardar</button>
          </div>
        </div>
      )}

      {hist.length === 0 ? (
        <p className="text-sm dp-muted py-3 text-center">Sin mediciones registradas todavía.</p>
      ) : (
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-[10px] uppercase tracking-wide dp-muted font-medium text-left">
                <th className="pb-1 pr-3">Fecha</th>
                <th className="pb-1 pr-3">Talla</th>
                <th className="pb-1 pr-3">Peso</th>
                <th className="pb-1 pr-3">IMC</th>
                <th className="pb-1 pr-3">% Grasa</th>
                <th className="pb-1 pr-3">M. muscular</th>
                <th className="pb-1 pr-3">% Agua</th>
                <th className="pb-1 pr-3">M. ósea</th>
                {!readOnly && <th className="pb-1" />}
              </tr>
            </thead>
            <tbody className="divide-y dp-divide-faint">
              {hist.map((c) => (
                <tr key={c.id} className="font-mono text-xs dp-ink">
                  <td className="py-1.5 pr-3">{c.fecha}</td>
                  <td className="py-1.5 pr-3">{c.talla || "—"} cm</td>
                  <td className="py-1.5 pr-3">{c.peso || "—"} kg</td>
                  <td className="py-1.5 pr-3">{imc(c.talla, c.peso)}</td>
                  <td className="py-1.5 pr-3">{c.grasaPct !== "" && c.grasaPct !== undefined ? `${c.grasaPct}%` : "—"}</td>
                  <td className="py-1.5 pr-3">{c.masaMuscular || "—"}</td>
                  <td className="py-1.5 pr-3">{c.aguaPct !== "" && c.aguaPct !== undefined ? `${c.aguaPct}%` : "—"}</td>
                  <td className="py-1.5 pr-3">{c.masaOsea || "—"}</td>
                  {!readOnly && <td className="py-1.5"><button onClick={() => eliminar(c.id)} className="dp-muted dp-hover-alert"><Trash2 size={12} /></button></td>}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}



function MovilidadEsferasSection({ cliente, onUpdate, readOnly }) {
  const lista = cliente.movilidadEsferas || [];

  const agregar = () => {
    const next = structuredClone(cliente);
    if (!next.movilidadEsferas) next.movilidadEsferas = [];
    next.movilidadEsferas.push({ id: uid(), patron: "", cráneo: "", tórax: "", pelvis: "", tobillo: "" });
    onUpdate(next);
  };
  const set = (id, key, value) => {
    const next = structuredClone(cliente);
    next.movilidadEsferas = (next.movilidadEsferas || []).map((m) => (m.id === id ? { ...m, [key]: value } : m));
    onUpdate(next);
  };
  const quitar = (id) => {
    const next = structuredClone(cliente);
    next.movilidadEsferas = (next.movilidadEsferas || []).filter((m) => m.id !== id);
    onUpdate(next);
  };

  return (
    <div className="bg-white rounded-2xl border dp-border-faint p-5">
      <div className="flex items-center justify-between mb-1">
        <h3 className="font-semibold dp-ink flex items-center gap-2"><Sparkles size={16} className="dp-text-brand" /> Movilidad por esferas</h3>
        {!readOnly && (
          <button onClick={agregar} className="text-xs font-medium dp-text-brand hover:underline flex items-center gap-1">
            <Plus size={13} /> Agregar patrón evaluado
          </button>
        )}
      </div>
      <p className="text-xs dp-muted mb-3">Elige tú el patrón (ej. flexión global tocando punta de pie) y anota cómo se mueve cada esfera — cráneo, tórax, pelvis, tobillo.</p>
      {lista.length === 0 && <p className="text-sm dp-muted py-4 text-center">Sin patrones evaluados todavía.</p>}
      <div className="space-y-3">
        {lista.map((m) => (
          <div key={m.id} className="rounded-xl dp-bg-faint p-3">
            <div className="flex items-center gap-2 mb-2">
              {readOnly ? (
                <p className="text-sm font-medium dp-ink flex-1">{m.patron || "Patrón sin nombre"}</p>
              ) : (
                <input value={m.patron} onChange={(e) => set(m.id, "patron", e.target.value)} placeholder="Nombre del patrón (ej. Flexión global tocando punta de pie)"
                  className="flex-1 text-sm font-medium border dp-border-hairline rounded-lg px-2 py-1 outline-none dp-focus-brand bg-white" />
              )}
              {!readOnly && <button onClick={() => quitar(m.id)} className="dp-muted dp-hover-alert"><Trash2 size={13} /></button>}
            </div>
            <div className="grid grid-cols-4 gap-2">
              {ESFERAS.map((esfera) => {
                const key = esfera.toLowerCase();
                return (
                  <div key={esfera}>
                    <label className="text-[10px] font-medium dp-muted uppercase">{esfera}</label>
                    {readOnly ? (
                      <p className="text-xs dp-ink mt-0.5">{m[key] || "—"}</p>
                    ) : (
                      <textarea rows={2} value={m[key] || ""} onChange={(e) => set(m.id, key, e.target.value)}
                        className="w-full mt-0.5 text-xs border dp-border-hairline rounded-md px-1.5 py-1 outline-none dp-focus-brand bg-white" />
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

const ALICIA_CAMPOS = [
  { key: "antiguedad", label: "Antigüedad", placeholder: "¿Cuándo comenzó el dolor?" },
  { key: "localizacion", label: "Localización", placeholder: "¿Dónde le duele?" },
  { key: "irradiacion", label: "Irradiación", placeholder: "¿Se extiende a otra parte del cuerpo?" },
  { key: "caracter", label: "Carácter", placeholder: "¿Cómo lo describe? (punzante, opresivo, quemante…)" },
  { key: "intensidad", label: "Intensidad (0-10)", placeholder: "Escala 0-10" },
  { key: "atenuacionAgravacion", label: "Atenuación / Agravación", placeholder: "¿Qué lo mejora o lo empeora?" },
];

function DolorAliciaSection({ cliente, onUpdate, readOnly }) {
  const alicia = cliente.dolorAlicia || {};
  const setCampo = (key, value) => {
    const next = structuredClone(cliente);
    if (!next.dolorAlicia) next.dolorAlicia = {};
    next.dolorAlicia[key] = value;
    onUpdate(next);
  };
  const algunaCargada = ALICIA_CAMPOS.some((c) => alicia[c.key]?.trim());

  return (
    <div className="bg-white rounded-2xl border dp-border-faint p-5">
      <h3 className="font-semibold dp-ink flex items-center gap-2 mb-1"><AlertTriangle size={16} className="dp-alert" /> Evaluación del dolor — ALICIA</h3>
      <p className="text-xs dp-muted mb-3">Antigüedad · Localización · Irradiación · Carácter · Intensidad · Atenuación/Agravación</p>
      {readOnly && !algunaCargada ? (
        <p className="text-sm dp-muted py-2">Sin dolor registrado.</p>
      ) : (
        <div className="grid grid-cols-2 gap-3">
          {ALICIA_CAMPOS.map((c) => (
            <div key={c.key}>
              <label className="text-xs font-medium dp-body">{c.label}</label>
              {readOnly ? (
                <p className="text-sm dp-ink mt-0.5">{alicia[c.key] || "—"}</p>
              ) : (
                <input value={alicia[c.key] || ""} onChange={(e) => setCampo(c.key, e.target.value)} placeholder={c.placeholder}
                  className="w-full mt-1 text-sm border dp-border-hairline rounded-lg px-3 py-1.5 outline-none dp-focus-brand" />
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function EvaluacionesCustomSection({ cliente, onUpdate, readOnly }) {
  const lista = cliente.evaluacionesCustom || [];

  const agregar = () => {
    const next = structuredClone(cliente);
    if (!next.evaluacionesCustom) next.evaluacionesCustom = [];
    next.evaluacionesCustom.push({ id: uid(), nombre: "", resultado: "" });
    onUpdate(next);
  };
  const set = (id, patch) => {
    const next = structuredClone(cliente);
    next.evaluacionesCustom = (next.evaluacionesCustom || []).map((e) => (e.id === id ? { ...e, ...patch } : e));
    onUpdate(next);
  };
  const quitar = (id) => {
    const next = structuredClone(cliente);
    next.evaluacionesCustom = (next.evaluacionesCustom || []).filter((e) => e.id !== id);
    onUpdate(next);
  };

  return (
    <div className="bg-white rounded-2xl border dp-border-faint p-5">
      <div className="flex items-center justify-between mb-1">
        <h3 className="font-semibold dp-ink flex items-center gap-2"><ClipboardList size={16} className="dp-text-amber" /> Evaluaciones específicas</h3>
        {!readOnly && (
          <button onClick={agregar} className="text-xs font-medium dp-text-brand hover:underline flex items-center gap-1">
            <Plus size={13} /> Agregar evaluación
          </button>
        )}
      </div>
      <p className="text-xs dp-muted mb-3">Pruebas puntuales según cada paciente — ej. Up and go test, unipodal test, knee to wall.</p>
      {lista.length === 0 && <p className="text-sm dp-muted py-4 text-center">Sin evaluaciones específicas agregadas.</p>}
      <div className="space-y-2">
        {lista.map((e) => (
          <div key={e.id} className="flex items-center gap-2">
            {readOnly ? (
              <>
                <span className="text-sm font-medium dp-ink" style={{ width: 160 }}>{e.nombre || "—"}</span>
                <span className="text-sm dp-body flex-1">{e.resultado || "—"}</span>
              </>
            ) : (
              <>
                <input value={e.nombre} onChange={(ev) => set(e.id, { nombre: ev.target.value })} placeholder="Nombre del test"
                  className="text-sm border dp-border-hairline rounded-lg px-2 py-1 outline-none dp-focus-brand" style={{ width: 160 }} />
                <input value={e.resultado} onChange={(ev) => set(e.id, { resultado: ev.target.value })} placeholder="Resultado / observación"
                  className="flex-1 text-sm border dp-border-hairline rounded-lg px-2 py-1 outline-none dp-focus-brand" />
                <button onClick={() => quitar(e.id)} className="dp-muted dp-hover-alert"><X size={14} /></button>
              </>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

function EvaluacionTab({ cliente, onUpdate, readOnly }) {
  const esAtleta = cliente.categoria === "Entrenamiento";
  const [mostrarRendimiento, setMostrarRendimiento] = useState(esAtleta);

  return (
    <div className="space-y-5">
      <PilaresSection cliente={cliente} onUpdate={onUpdate} readOnly={readOnly} />
      <ComposicionCorporalSection cliente={cliente} onUpdate={onUpdate} readOnly={readOnly} />
      <FmsTab cliente={cliente} onUpdate={onUpdate} readOnly={readOnly} />
      <DolorAliciaSection cliente={cliente} onUpdate={onUpdate} readOnly={readOnly} />
      <MovilidadEsferasSection cliente={cliente} onUpdate={onUpdate} readOnly={readOnly} />
      <EvaluacionesCustomSection cliente={cliente} onUpdate={onUpdate} readOnly={readOnly} />

      <div className="bg-white rounded-2xl border dp-border-faint p-5">
        <button onClick={() => setMostrarRendimiento((v) => !v)} className="w-full flex items-center justify-between">
          <h3 className="font-semibold dp-ink flex items-center gap-2"><TrendingUp size={16} /> Evaluación de rendimiento {!esAtleta && <span className="text-xs font-normal dp-muted">(no marcado como atleta)</span>}</h3>
          <ChevronRight size={16} className={`dp-muted transition-transform ${mostrarRendimiento ? "rotate-90" : ""}`} />
        </button>
        {mostrarRendimiento && (
          <div className="mt-4">
            <EvolucionTab cliente={cliente} onUpdate={onUpdate} readOnly={readOnly} />
          </div>
        )}
      </div>
    </div>
  );
}

function EvolucionTab({ cliente, onUpdate, readOnly }) {
  const hist = [...cliente.prHistorial].sort((a, b) => a.fecha.localeCompare(b.fecha));
  const GRUPOS = [
    { titulo: "Fuerza", unidad: "kg", metrics: [
      { key: "sentadilla", label: "Sentadilla" },
      { key: "pesoMuerto", label: "Peso muerto" },
      { key: "pressBanca", label: "Press banca" },
      { key: "pressMilitar", label: "Press militar" },
    ]},
    { titulo: "Saltos", unidad: "cm", metrics: [
      { key: "broadJump", label: "Broad jump" },
      { key: "abalakovJump", label: "Abalakov" },
      { key: "cmj", label: "CMJ" },
      { key: "squatJump", label: "Squat jump (SJ)" },
    ]},
    { titulo: "Fuerza funcional", unidad: "", metrics: [
      { key: "agarreDer", label: "Fuerza de agarre der. (kg)" },
      { key: "agarreIzq", label: "Fuerza de agarre izq. (kg)" },
      { key: "deadHang", label: "Dead hang (seg)" },
      { key: "pullUps", label: "Pull ups (reps)" },
      { key: "pushUp", label: "Push up (reps)" },
      { key: "planchaFrontal", label: "Plancha frontal (seg)" },
      { key: "planchaLateralDer", label: "Plancha lateral der. (seg)" },
      { key: "planchaLateralIzq", label: "Plancha lateral izq. (seg)" },
      { key: "pararseDelSuelo", label: "Pararse del suelo (puntaje, 10=sin apoyos)" },
    ]},
  ];
  const metrics = GRUPOS.flatMap((g) => g.metrics);
  const camposVacios = Object.fromEntries(metrics.map((m) => [m.key, ""]));
  const fmtFecha = (f) => { const d = new Date(f + "T00:00:00"); return isNaN(d) ? f : d.toLocaleDateString("es-CL", { day: "2-digit", month: "short", year: "2-digit" }); };
  const maxDe = (key) => Math.max(...hist.map((h) => h[key] || 0), 1);

  const [showAdd, setShowAdd] = useState(false);
  const [draft, setDraft] = useState({ fecha: new Date().toISOString().slice(0, 10), mesociclo: "", objetivo: "", ...camposVacios });

  const agregar = () => {
    if (!draft.mesociclo.trim()) return;
    const next = structuredClone(cliente);
    const entrada = { fecha: draft.fecha, mesociclo: draft.mesociclo.trim(), objetivo: draft.objetivo.trim() };
    metrics.forEach((m) => { entrada[m.key] = Number(draft[m.key]) || 0; });
    next.prHistorial.push(entrada);
    onUpdate(next);
    setDraft({ fecha: new Date().toISOString().slice(0, 10), mesociclo: "", objetivo: "", ...camposVacios });
    setShowAdd(false);
  };

  return (
    <div className="space-y-4">
      {!readOnly && (
        <div className="flex justify-end">
          <button onClick={() => setShowAdd((v) => !v)} className="flex items-center gap-1.5 dp-bg-brand text-white text-sm font-medium px-3.5 py-2 rounded-xl dp-hover-brand-dark transition-colors">
            <Plus size={16} /> Nuevo registro de mesociclo
          </button>
        </div>
      )}
      {showAdd && (
        <div className="bg-white rounded-2xl border dp-border-faint p-4 space-y-3">
          <div className="grid grid-cols-3 gap-3">
            <div>
              <label className="text-xs font-medium dp-body">Fecha</label>
              <input type="date" value={draft.fecha} onChange={(e) => setDraft({ ...draft, fecha: e.target.value })} className="w-full mt-1 border dp-border-hairline rounded-lg px-3 py-1.5 text-sm outline-none dp-focus-brand" />
            </div>
            <div>
              <label className="text-xs font-medium dp-body">Mesociclo</label>
              <input value={draft.mesociclo} onChange={(e) => setDraft({ ...draft, mesociclo: e.target.value })} placeholder="Ej. Mesociclo 5" className="w-full mt-1 border dp-border-hairline rounded-lg px-3 py-1.5 text-sm outline-none dp-focus-brand" />
            </div>
            <div>
              <label className="text-xs font-medium dp-body">Objetivo de la fase</label>
              <input value={draft.objetivo} onChange={(e) => setDraft({ ...draft, objetivo: e.target.value })} placeholder="Ej. Fuerza máxima / Fuerza explosiva / Pliometría" className="w-full mt-1 border dp-border-hairline rounded-lg px-3 py-1.5 text-sm outline-none dp-focus-brand" />
            </div>
          </div>
          {GRUPOS.map((g) => (
            <div key={g.titulo}>
              <p className="text-xs font-semibold dp-text-brand uppercase tracking-wide mb-1.5">{g.titulo}</p>
              <div className="grid grid-cols-4 gap-3">
                {g.metrics.map((m) => (
                  <div key={m.key}>
                    <label className="text-[11px] font-medium dp-body">{m.label}</label>
                    <input type="number" value={draft[m.key]} onChange={(e) => setDraft({ ...draft, [m.key]: e.target.value })} className="w-full mt-1 border dp-border-hairline rounded-lg px-2 py-1.5 text-sm outline-none dp-focus-brand font-mono" />
                  </div>
                ))}
              </div>
            </div>
          ))}
          <button onClick={agregar} disabled={!draft.mesociclo.trim()} className="dp-bg-brand disabled:opacity-40 text-white font-medium px-4 py-2 rounded-xl dp-hover-brand-dark transition-colors">
            Guardar registro
          </button>
        </div>
      )}

      {hist.length === 0 ? (
        <p className="text-sm dp-muted bg-white rounded-2xl border dp-border-faint p-8 text-center">Todavía no hay marcas registradas para este cliente.</p>
      ) : (
        <div className="bg-white rounded-2xl border dp-border-faint p-5">
          <h3 className="font-semibold dp-ink mb-1 flex items-center gap-2"><TrendingUp size={16} /> Evolución de marcas</h3>
          <p className="text-xs dp-muted mb-4">Cada columna es un mesociclo — pasa el cursor sobre las barras para ver el detalle.</p>

          <div className="grid gap-2 mb-4" style={{ gridTemplateColumns: `repeat(${hist.length}, minmax(0,1fr))` }}>
            {hist.map((h, i) => (
              <div key={i} className="text-center">
                <p className="font-mono text-[10px] dp-muted">{fmtFecha(h.fecha)}</p>
                <p className="text-[11px] font-semibold dp-ink truncate">{h.mesociclo}</p>
                {h.objetivo && <p className="text-[10px] dp-text-brand truncate">{h.objetivo}</p>}
              </div>
            ))}
          </div>

          {GRUPOS.map((g) => (
            <div key={g.titulo} className="mb-6 last:mb-0">
              <div className="flex items-center justify-between mb-2">
                <p className="text-xs font-semibold dp-text-brand uppercase tracking-wide">{g.titulo}</p>
                {g.titulo === "Saltos" && (
                  <div className="flex items-center gap-1.5 flex-wrap">
                    {hist.map((h, i) => {
                      if (!h.cmj || !h.squatJump) return null;
                      const deficit = ((h.cmj - h.squatJump) / h.squatJump) * 100;
                      const bajo = deficit < 15;
                      return (
                        <span key={i} title={`${h.mesociclo}: (CMJ-SJ)/SJ`}
                          className={`text-[10px] font-mono font-medium px-2 py-0.5 rounded-full text-white ${bajo ? "dp-bg-alert" : "dp-bg-brand"}`}>
                          Déficit expl. {deficit.toFixed(0)}%
                        </span>
                      );
                    })}
                  </div>
                )}
              </div>
              {g.titulo === "Saltos" && hist.some((h) => h.cmj && h.squatJump && ((h.cmj - h.squatJump) / h.squatJump) * 100 < 15) && (
                <p className="text-[11px] dp-alert mb-2 flex items-center gap-1"><AlertTriangle size={12} /> Déficit explosivo bajo 15% — el CMJ casi no mejora al SJ, sugiere poco aprovechamiento del ciclo de estiramiento-acortamiento (foco en trabajo pliométrico/reactivo).</p>
              )}
              <div className="space-y-4">
                {g.metrics.map((m) => {
                  const max = maxDe(m.key);
                  return (
                    <div key={m.key}>
                      <p className="text-xs font-medium dp-muted mb-1">{m.label}</p>
                      <div className="flex items-end gap-2 h-16">
                        {hist.map((h, i) => {
                          const v = h[m.key] || 0;
                          const isPR = v === Math.max(...hist.map((x) => x[m.key] || 0)) && v > 0;
                          return (
                            <div key={i} className="flex-1 flex flex-col items-center justify-end gap-1 h-full">
                              {isPR && <Sparkles size={11} className="dp-text-amber" />}
                              <div className="w-full rounded-t-md dp-bg-brand" style={{ height: `${(v / max) * 100}%`, opacity: isPR ? 1 : 0.55 }} title={`${h.mesociclo} · ${fmtFecha(h.fecha)}: ${v}`} />
                            </div>
                          );
                        })}
                      </div>
                      <div className="flex gap-2 mt-1">
                        {hist.map((h, i) => (
                          <span key={i} className="flex-1 text-center font-mono text-[10px] dp-muted">{h[m.key] || "—"}</span>
                        ))}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
          </div>
      )}
    </div>
  );
}

