/* --------------------------- Biblioteca de ejercicios --------------------------- */

function BibliotecaView({ biblioteca, onUpdate }) {
  const [q, setQ] = useState("");
  const [showAdd, setShowAdd] = useState(false);
  const [nuevoNombre, setNuevoNombre] = useState("");
  const [nuevoLink, setNuevoLink] = useState("");

  const filtrados = biblioteca.filter((b) => b.nombre.toLowerCase().includes(q.toLowerCase()));

  const editLink = (id, link) => onUpdate(biblioteca.map((b) => (b.id === id ? { ...b, link } : b)));
  const editNombre = (id, nombre) => onUpdate(biblioteca.map((b) => (b.id === id ? { ...b, nombre } : b)));
  const eliminar = (id) => onUpdate(biblioteca.filter((b) => b.id !== id));

  const agregar = () => {
    if (!nuevoNombre.trim()) return;
    onUpdate([...biblioteca, { id: uid(), nombre: nuevoNombre.trim(), link: nuevoLink.trim() }]);
    setNuevoNombre(""); setNuevoLink(""); setShowAdd(false);
  };

  return (
    <div>
      <div className="flex items-center justify-between mb-5">
        <div>
          <h1 className="text-2xl font-semibold dp-ink" style={{ fontFamily: "'Space Grotesk', sans-serif" }}>Biblioteca de ejercicios</h1>
          <p className="text-sm dp-muted mt-0.5">{biblioteca.length} ejercicios · se sugieren automáticamente al planificar</p>
        </div>
        <button onClick={() => setShowAdd((v) => !v)} className="flex items-center gap-1.5 dp-bg-brand text-white text-sm font-medium px-3.5 py-2 rounded-xl dp-hover-brand-dark transition-colors">
          <Plus size={16} /> Agregar ejercicio
        </button>
      </div>

      {showAdd && (
        <div className="bg-white rounded-2xl border dp-border-faint p-4 mb-4 flex items-end gap-3">
          <div className="flex-1">
            <label className="text-xs font-medium dp-body">Nombre</label>
            <input value={nuevoNombre} onChange={(e) => setNuevoNombre(e.target.value)} className="w-full mt-1 border dp-border-hairline rounded-lg px-3 py-1.5 text-sm outline-none dp-focus-brand" placeholder="Ej. Goblet squat" />
          </div>
          <div className="flex-1">
            <label className="text-xs font-medium dp-body">Link del video</label>
            <input value={nuevoLink} onChange={(e) => setNuevoLink(e.target.value)} className="w-full mt-1 border dp-border-hairline rounded-lg px-3 py-1.5 text-sm outline-none dp-focus-brand" placeholder="https://youtube.com/…" />
          </div>
          <button onClick={agregar} disabled={!nuevoNombre.trim()} className="dp-bg-brand disabled:opacity-40 text-white font-medium px-4 py-1.5 rounded-lg dp-hover-brand-dark transition-colors">
            Guardar
          </button>
        </div>
      )}

      <div className="relative mb-4">
        <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 dp-muted" />
        <input
          value={q} onChange={(e) => setQ(e.target.value)}
          placeholder="Buscar ejercicio…"
          className="w-full bg-white border dp-border-hairline rounded-xl pl-9 pr-3 py-2.5 text-sm outline-none dp-focus-brand"
        />
      </div>

      <div className="bg-white rounded-2xl border dp-border-faint divide-y dp-divide-faint">
        {filtrados.length === 0 && (
          <p className="text-sm dp-muted py-10 text-center">Ningún ejercicio coincide con "{q}".</p>
        )}
        {filtrados.map((b) => (
          <div key={b.id} className="flex items-center gap-3 p-3">
            <Dumbbell size={15} className="dp-muted shrink-0" />
            <input
              value={b.nombre} onChange={(e) => editNombre(b.id, e.target.value)}
              className="flex-1 text-sm dp-ink border-none outline-none bg-transparent"
            />
            <input
              value={b.link || ""} onChange={(e) => editLink(b.id, e.target.value)}
              placeholder="Sin link — pégalo aquí"
              className="flex-1 text-xs dp-text-brand border-none outline-none bg-transparent"
            />
            {b.link && (
              <a href={b.link} target="_blank" rel="noreferrer" className="dp-muted dp-hover-ink shrink-0" title="Abrir video">
                <Play size={14} />
              </a>
            )}
            <button onClick={() => eliminar(b.id)} className="dp-muted dp-hover-alert shrink-0"><Trash2 size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  );
}

/* --------------------------------- Agenda --------------------------------- */

function Agenda({ data, onUpdateAppts, onAddAppt }) {
  const [showModal, setShowModal] = useState(false);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().slice(0, 10));

  const citas = data.appts.filter((a) => a.fecha === selectedDate).sort((a, b) => a.hora.localeCompare(b.hora));

  const changeDay = (delta) => {
    const d = new Date(selectedDate + "T00:00:00");
    d.setDate(d.getDate() + delta);
    setSelectedDate(d.toISOString().slice(0, 10));
  };

  const setEstado = (id, estado) => {
    onUpdateAppts(data.appts.map((a) => (a.id === id ? { ...a, estado } : a)));
  };
  const removeAppt = (id) => onUpdateAppts(data.appts.filter((a) => a.id !== id));

  const dateLabel = new Date(selectedDate + "T00:00:00").toLocaleDateString("es-CL", { weekday: "long", day: "numeric", month: "long" });

  return (
    <div>
      <div className="flex items-center justify-between mb-5">
        <h1 className="text-2xl font-semibold dp-ink" style={{ fontFamily: "'Space Grotesk', sans-serif" }}>Agenda</h1>
        <button onClick={() => setShowModal(true)} className="flex items-center gap-1.5 dp-bg-brand text-white text-sm font-medium px-3.5 py-2 rounded-xl dp-hover-brand-dark transition-colors">
          <Plus size={16} /> Agendar sesión
        </button>
      </div>

      <div className="flex items-center justify-between bg-white rounded-2xl border dp-border-faint p-3 mb-4">
        <button onClick={() => changeDay(-1)} className="p-1.5 hover:dp-bg-faint rounded-lg"><ChevronLeft size={18} /></button>
        <span className="text-sm font-medium dp-ink capitalize">{dateLabel}</span>
        <button onClick={() => changeDay(1)} className="p-1.5 hover:dp-bg-faint rounded-lg"><ChevronRight size={18} /></button>
      </div>

      <div className="bg-white rounded-2xl border dp-border-faint divide-y dp-divide-faint">
        {citas.length === 0 && (
          <p className="text-sm dp-muted py-10 text-center">No hay sesiones agendadas este día. Usa "Agendar sesión" para sumar una.</p>
        )}
        {citas.map((c) => (
          <div key={c.id} className="flex items-center gap-3 p-4">
            <div className="flex items-center gap-1.5 w-16 text-sm font-mono dp-body"><Clock size={13} />{c.hora}</div>
            <Avatar initials={c.cliente.split(" ").map((n) => n[0]).slice(0, 2).join("")} size={34} />
            <div className="flex-1">
              <p className="text-sm font-medium dp-ink">{c.cliente}</p>
              <p className="text-xs dp-muted">{c.tipo}</p>
            </div>
            <select value={c.estado} onChange={(e) => setEstado(c.id, e.target.value)} className="text-xs border dp-border-hairline rounded-lg px-2 py-1 outline-none">
              <option value="pendiente">Pendiente</option>
              <option value="confirmada">Confirmada</option>
              <option value="alerta">Alerta leve</option>
              <option value="cancelada">Cancelada</option>
            </select>
            <button onClick={() => removeAppt(c.id)} className="dp-muted dp-hover-alert"><Trash2 size={15} /></button>
          </div>
        ))}
      </div>

      {showModal && (
        <NewApptModal
          clients={data.clients}
          defaultDate={selectedDate}
          onClose={() => setShowModal(false)}
          onCreate={(appt) => { onAddAppt(appt); setShowModal(false); }}
        />
      )}
    </div>
  );
}

function NewApptModal({ clients, defaultDate, onClose, onCreate }) {
  const [clienteId, setClienteId] = useState(clients[0]?.id || "");
  const [fecha, setFecha] = useState(defaultDate);
  const [hora, setHora] = useState("09:00");
  const [tipo, setTipo] = useState("Kinesiología");

  const submit = () => {
    const cliente = clients.find((c) => c.id === clienteId);
    if (!cliente) return;
    onCreate({ id: uid(), clienteId, cliente: cliente.nombre, fecha, hora, tipo, estado: "pendiente" });
  };

  return (
    <div className="fixed inset-0 dp-bg-scrim flex items-center justify-center z-50 p-4" onClick={onClose}>
      <div className="bg-white rounded-2xl max-w-sm w-full p-6" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-semibold dp-ink" style={{ fontFamily: "'Space Grotesk', sans-serif" }}>Agendar sesión</h2>
          <button onClick={onClose}><X size={18} className="dp-muted" /></button>
        </div>
        <div className="space-y-3">
          <div>
            <label className="text-xs font-medium dp-body">Cliente</label>
            <select value={clienteId} onChange={(e) => setClienteId(e.target.value)} className="w-full mt-1 border dp-border-hairline rounded-lg px-3 py-2 text-sm outline-none dp-focus-brand">
              {clients.map((c) => <option key={c.id} value={c.id}>{c.nombre}</option>)}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="text-xs font-medium dp-body">Fecha</label>
              <input type="date" value={fecha} onChange={(e) => setFecha(e.target.value)} className="w-full mt-1 border dp-border-hairline rounded-lg px-3 py-2 text-sm outline-none dp-focus-brand" />
            </div>
            <div>
              <label className="text-xs font-medium dp-body">Hora</label>
              <input type="time" value={hora} onChange={(e) => setHora(e.target.value)} className="w-full mt-1 border dp-border-hairline rounded-lg px-3 py-2 text-sm outline-none dp-focus-brand" />
            </div>
          </div>
          <div>
            <label className="text-xs font-medium dp-body">Tipo de sesión</label>
            <select value={tipo} onChange={(e) => setTipo(e.target.value)} className="w-full mt-1 border dp-border-hairline rounded-lg px-3 py-2 text-sm outline-none dp-focus-brand">
              <option>Kinesiología</option>
              <option>Rendimiento</option>
              <option>Evaluación</option>
              <option>Entrenamiento grupal</option>
            </select>
          </div>
        </div>
        <button onClick={submit} disabled={!clienteId} className="w-full mt-5 dp-bg-brand disabled:opacity-40 text-white font-medium py-2.5 rounded-xl dp-hover-brand-dark transition-colors">
          Agendar
        </button>
      </div>
    </div>
  );
}

/* ------------------------------ Portal Cliente ------------------------------ */

function PortalCliente({ cliente, onUpdateClient }) {
  const [tab, setTab] = useState("plan");

  return (
    <div>
      {cliente && (
        <>
          <div className="flex items-center gap-3 mb-5">
            <Avatar initials={cliente.iniciales} size={48} tone="amber" />
            <div>
              <h1 className="text-2xl font-semibold dp-ink" style={{ fontFamily: "'Space Grotesk', sans-serif" }}>Hola, {cliente.nombre.split(" ")[0]}</h1>
              <p className="text-sm dp-muted">{(cliente.plan.semanas.find((s) => s.id === cliente.plan.semanaActivaId) || cliente.plan.semanas[0])?.mesociclo || "Semana en curso"}</p>
            </div>
          </div>

          <div className="flex gap-1 mb-5 dp-bg-faint p-1 rounded-xl w-fit">
            {[{ id: "plan", label: "Mi rutina", icon: Dumbbell }, { id: "sesiones", label: "Mis sesiones", icon: CheckCircle2 }, { id: "evolucion", label: "Mi progreso", icon: TrendingUp }].map((t) => (
              <button key={t.id} onClick={() => setTab(t.id)} className={`flex items-center gap-1.5 px-3.5 py-1.5 rounded-lg text-sm font-medium transition-colors ${tab === t.id ? "bg-white dp-ink shadow-sm" : "dp-body"}`}>
                <t.icon size={15} /> {t.label}
              </button>
            ))}
          </div>

          {tab === "plan" && <PlanTab cliente={cliente} onUpdate={onUpdateClient} readOnly allowClientComment />}
          {tab === "sesiones" && <SesionesTab cliente={cliente} onUpdate={() => {}} readOnly />}
          {tab === "evolucion" && <EvolucionTab cliente={cliente} onUpdate={() => {}} readOnly />}
        </>
      )}
    </div>
  );
}

/* ------------------------------ Acceso ------------------------------ */
/* Pantalla de entrada — separa el acceso del equipo DIPRA del acceso de
   cada atleta. Un atleta elige su nombre una vez y queda anclado a su
   propia ficha: no puede navegar a la de otra persona desde aquí. */

function AccessGate({ clients, onEnterPro, onEnterAtleta }) {
  const [mode, setMode] = useState(null); // null | "atleta"
  const [clienteId, setClienteId] = useState("");

  return (
    <div style={{
      minHeight: "100vh", background: "#F3F6F2", display: "flex", flexDirection: "column",
      alignItems: "center", justifyContent: "center", padding: "0 24px", fontFamily: "'Inter', sans-serif",
    }}>
      <div style={{
        width: 96, height: 96, background: "#000000", borderRadius: 24, display: "flex",
        alignItems: "center", justifyContent: "center", padding: 12, marginBottom: 16,
      }}>
        <img src={DIPRA_LOGO} alt="DIPRA" style={{ width: "100%", height: "100%", objectFit: "contain" }} />
      </div>
      <h1 style={{ fontFamily: "'Space Grotesk', sans-serif", fontSize: 30, fontWeight: 600, color: "#0E1210", margin: "0 0 4px" }}>DIPRA</h1>
      <p style={{ fontSize: 12, letterSpacing: "0.2em", color: "#5B655F", fontWeight: 500, textTransform: "uppercase", marginBottom: 40 }}>
        Entrenamiento &amp; Kinesiología Integral
      </p>

      {mode !== "atleta" ? (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, width: "100%", maxWidth: 420 }}>
          <button
            onClick={onEnterPro}
            style={{
              borderRadius: 16, padding: 24, textAlign: "left", background: "#0E1210",
              border: "none", cursor: "pointer", color: "#FFFFFF",
            }}
          >
            <Stethoscope size={22} color="#FFFFFF" style={{ marginBottom: 24, display: "block" }} />
            <p style={{ fontFamily: "'Space Grotesk', sans-serif", fontWeight: 600, color: "#FFFFFF", margin: 0 }}>Acceso Admin / Profesional</p>
            <p style={{ color: "rgba(255,255,255,0.6)", fontSize: 12, marginTop: 4 }}>Fichas, planificación y agenda</p>
          </button>
          <button
            onClick={() => setMode("atleta")}
            style={{
              borderRadius: 16, padding: 24, textAlign: "left", color: "#FFFFFF", border: "none", cursor: "pointer",
              background: "linear-gradient(135deg, #1E8449, #A8CC3C)",
            }}
          >
            <Dumbbell size={22} color="#FFFFFF" style={{ marginBottom: 24, display: "block" }} />
            <p style={{ fontFamily: "'Space Grotesk', sans-serif", fontWeight: 600, margin: 0 }}>Acceso Atleta / Usuario</p>
            <p style={{ color: "rgba(255,255,255,0.85)", fontSize: 12, marginTop: 4 }}>Tu rutina y tu progreso</p>
          </button>
        </div>
      ) : (
        <div style={{ width: "100%", maxWidth: 384, background: "#FFFFFF", borderRadius: 16, border: "1px solid rgba(0,0,0,0.08)", padding: 24 }}>
          <button onClick={() => setMode(null)} style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, color: "#7A857F", marginBottom: 16, background: "none", border: "none", cursor: "pointer", padding: 0 }}>
            <ArrowLeft size={13} /> Volver
          </button>
          <label style={{ fontSize: 12, fontWeight: 500, color: "#4A534F" }}>¿Quién eres?</label>
          <select
            value={clienteId} onChange={(e) => setClienteId(e.target.value)}
            style={{ width: "100%", marginTop: 6, border: "1px solid rgba(0,0,0,0.15)", borderRadius: 8, padding: "10px 12px", fontSize: 14, outline: "none" }}
          >
            <option value="">Selecciona tu nombre…</option>
            {clients.map((c) => <option key={c.id} value={c.id}>{c.nombre}</option>)}
          </select>
          <button
            disabled={!clienteId}
            onClick={() => onEnterAtleta(clienteId)}
            style={{
              width: "100%", marginTop: 16, color: "#FFFFFF", fontWeight: 500, padding: "10px 0", borderRadius: 12,
              border: "none", cursor: clienteId ? "pointer" : "not-allowed", opacity: clienteId ? 1 : 0.4,
              background: "linear-gradient(135deg, #1E8449, #A8CC3C)",
            }}
          >
            Entrar
          </button>
          <p style={{ fontSize: 11, color: "#9AA39C", marginTop: 12, textAlign: "center" }}>Cada atleta ve solo su propia ficha y rutina.</p>
        </div>
      )}
    </div>
  );
}

/* --------------------------------- App --------------------------------- */

export default function DipraApp() {
  useFonts();
  useDipraStyles();
  const { data, setData, persistMerge, loading } = useDipraData();
  const [gate, setGate] = useState(null); // null | "pro" | "atleta"
  const [myClientId, setMyClientId] = useState(null);
  const [view, setView] = useState("inicio");
  const [openClientId, setOpenClientId] = useState(null);
  const [showNewClient, setShowNewClient] = useState(false);
  const [postCreateClientId, setPostCreateClientId] = useState(null);

  if (loading || !data) {
    return (
      <div className="min-h-screen flex items-center justify-center dp-bg-app">
        <p className="text-sm dp-muted">Cargando DIPRA…</p>
      </div>
    );
  }

  if (!gate) {
    return (
      <AccessGate
        clients={data.clients}
        onEnterPro={() => setGate("pro")}
        onEnterAtleta={(id) => { setMyClientId(id); setGate("atleta"); }}
      />
    );
  }

  const role = gate === "pro" ? "pro" : "cliente";

  const openClient = data.clients.find((c) => c.id === openClientId);
  const myClient = data.clients.find((c) => c.id === myClientId);

  const updateClient = (nextClient) => {
    setData({ ...data, clients: data.clients.map((c) => (c.id === nextClient.id ? nextClient : c)) });
  };
  const deleteClient = (id) => {
    setData({ ...data, clients: data.clients.filter((c) => c.id !== id) });
    setOpenClientId(null);
  };
  const createClient = (client) => {
    persistMerge((latest) => ({ ...latest, clients: [...(latest.clients || []), client] }));
    setShowNewClient(false);
    setPostCreateClientId(client.id);
  };
  const updateAppts = (appts) => setData({ ...data, appts });
  const addAppt = (appt) => persistMerge((latest) => ({ ...latest, appts: [...(latest.appts || []), appt] }));
  const saveToBiblioteca = (item) => persistMerge((latest) => ({ ...latest, biblioteca: [...(latest.biblioteca || []), item] }));

  const NAV = [
    { id: "inicio", label: "Inicio", icon: LayoutDashboard },
    { id: "clientes", label: "Clientes", icon: Users },
    { id: "agenda", label: "Agenda", icon: CalendarDays },
    { id: "biblioteca", label: "Biblioteca", icon: Dumbbell },
  ];

  return (
    <div className="min-h-screen dp-bg-app flex" style={{ fontFamily: "'Inter', sans-serif" }}>
      <aside className="w-60 shrink-0 p-5 flex flex-col" style={{ background: "#0E1B14" }}>
        <div className="flex items-center justify-between mb-2">
          <div className="w-16 h-16 bg-black rounded-2xl flex items-center justify-center p-2">
            <img src={DIPRA_LOGO} alt="DIPRA" className="w-full h-full object-contain" />
          </div>
        </div>
        <p className="text-[10px] tracking-[0.15em] dp-text-sidebar-muted font-medium mt-4 mb-6">
          EVALUACIÓN · PLANIFICACIÓN · EVOLUCIÓN
        </p>

        {role === "pro" && (
          <nav className="space-y-1.5">
            {NAV.map((n) => (
              <NavItem key={n.id} icon={n.icon} label={n.label} active={view === n.id && !openClientId} onClick={() => { setView(n.id); setOpenClientId(null); }} />
            ))}
          </nav>
        )}

        <div className="mt-auto pt-4 border-t dp-border-white-10 flex items-center justify-between">
          <div className="flex items-center gap-2 min-w-0">
            <Avatar initials={role === "pro" ? "NN" : (myClient?.iniciales || "?")} size={30} tone={role === "pro" ? "teal" : "amber"} />
            <div className="min-w-0">
              <p className="text-xs font-medium text-white truncate">{role === "pro" ? "Nicolás Navarro" : myClient?.nombre}</p>
              <p className="text-[10px] dp-text-sidebar-muted">{role === "pro" ? "Coach / Kinesiólogo" : "Atleta"}</p>
            </div>
          </div>
          <button onClick={() => { setGate(null); setMyClientId(null); setOpenClientId(null); }} title="Salir" className="dp-text-faint dp-hover-alert shrink-0">
            <X size={15} />
          </button>
        </div>
      </aside>

      <main className="flex-1 p-8 max-w-5xl">
        {role === "cliente" ? (
          <PortalCliente cliente={myClient} onUpdateClient={updateClient} />
        ) : openClient ? (
          <ClienteDetalle cliente={openClient} onBack={() => setOpenClientId(null)} onUpdate={updateClient} onDelete={deleteClient} readOnly={false} biblioteca={data.biblioteca || []} onSaveToBiblioteca={saveToBiblioteca} onAgendar={() => { setView("agenda"); setOpenClientId(null); }} />
        ) : view === "inicio" ? (
          <Inicio data={data} onGoAgenda={() => setView("agenda")} onGoClient={(id) => setOpenClientId(id)} />
        ) : view === "clientes" ? (
          <ClientesList data={data} onOpen={setOpenClientId} onAdd={() => setShowNewClient(true)} />
        ) : view === "biblioteca" ? (
          <BibliotecaView biblioteca={data.biblioteca || []} onUpdate={(b) => setData({ ...data, biblioteca: b })} />
        ) : (
          <Agenda data={data} onUpdateAppts={updateAppts} onAddAppt={addAppt} />
        )}
      </main>

      {showNewClient && <NewClientModal onClose={() => setShowNewClient(false)} onCreate={createClient} />}
      {postCreateClientId && (
        <PostCreateModal
          clienteNombre={data.clients.find((c) => c.id === postCreateClientId)?.nombre || ""}
          onAgendar={() => { setView("agenda"); setOpenClientId(null); setPostCreateClientId(null); }}
          onVerFicha={() => { setOpenClientId(postCreateClientId); setPostCreateClientId(null); }}
          onCerrar={() => setPostCreateClientId(null)}
        />
      )}
    </div>
  );
}
